// Hook PoC server. Receives Claude Code and Codex hook events, holds approval and
// question hooks open until someone answers, and polls `claude agents --json`.
// No dependencies: `node server.mjs`, then open http://127.0.0.1:7777
import http from "node:http";
import { execFile } from "node:child_process";
import { appendFileSync, writeFileSync } from "node:fs";
import { randomUUID } from "node:crypto";

const PORT = Number(process.env.PORT ?? 7777);
const LOG = new URL("./events.jsonl", import.meta.url).pathname;
const HOLD_MS = Number(process.env.HOLD_MS ?? 280_000); // give up before the hook timeout
writeFileSync(LOG, "");

const t0 = Date.now();
const pending = new Map(); // id -> { id, agent, kind, event, resolve, since }

function log(entry) {
  const line = { t: ((Date.now() - t0) / 1000).toFixed(1), ...entry };
  appendFileSync(LOG, JSON.stringify(line) + "\n");
  const { t, src, event, tool, session, note } = line;
  console.log(`[${t}s] ${src.padEnd(14)} ${event ?? ""} ${tool ?? ""} ${session ?? ""} ${note ?? ""}`);
}

function summarize(agent, ev) {
  return {
    src: `hook:${agent}`,
    event: ev.hook_event_name,
    tool: ev.tool_name,
    session: ev.session_id?.slice(0, 8),
    note: ev.notification_type ?? ev.reason ?? ev.last_assistant_message?.slice(0, 80) ?? "",
  };
}

// Replies for a held hook. `pass` means "no decision": the agent falls back to its own UI.
function reply(agent, kind, ev, answer) {
  if (answer.action === "pass") return agent === "codex" ? "{}" : "";
  // Block the question tool and hand the answer to the model as the deny reason.
  if (kind === "question" && answer.action === "deny") {
    return JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason: `The user already answered this question from the dashboard. Their answer: ${answer.text}`,
      },
    });
  }
  if (kind === "question") {
    const questions = ev.tool_input?.questions ?? [];
    const answers = Object.fromEntries(questions.map((q) => [q.question, answer.text ?? q.options?.[0]?.label ?? "yes"]));
    return JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "allow",
        updatedInput: { ...ev.tool_input, answers },
      },
    });
  }
  const decision = answer.action === "allow"
    ? { behavior: "allow" }
    : { behavior: "deny", message: answer.text ?? "Denied from the dashboard." };
  return JSON.stringify({ hookSpecificOutput: { hookEventName: "PermissionRequest", decision } });
}

async function readBody(req) {
  let body = "";
  for await (const chunk of req) body += chunk;
  return body;
}

const page = `<!doctype html><meta charset="utf-8"><title>Hook PoC</title>
<style>body{font:14px system-ui;margin:16px;max-width:900px}pre{background:#eee;padding:8px;white-space:pre-wrap}
.p{border:2px solid #c80;padding:8px;margin:8px 0}</style>
<h1>Pending hook requests</h1><div id=p></div><h2>Log</h2><pre id=l></pre>
<script>
async function act(id, action){const text=prompt('Optional text (deny reason / answer):')||undefined;
 await fetch('/answer/'+id,{method:'POST',body:JSON.stringify({action,text})});tick()}
async function tick(){const s=await (await fetch('/state')).json();
 p.innerHTML=s.pending.map(x=>'<div class=p><b>'+x.agent+' '+x.kind+'</b> '+(x.tool||'')+' — waiting '+x.waiting+'s<pre>'+
  JSON.stringify(x.input,null,1).slice(0,600)+'</pre>'+['allow','deny','pass'].map(a=>'<button onclick="act(\\''+x.id+'\\',\\''+a+'\\')">'+a+'</button>').join(' ')+'</div>').join('')||'none';
 l.textContent=s.log}
setInterval(tick,1000);tick()</script>`;

http.createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  const parts = url.pathname.split("/").filter(Boolean);

  if (req.method === "GET" && url.pathname === "/") return res.end(page);
  if (req.method === "GET" && url.pathname === "/state") {
    const { readFileSync } = await import("node:fs");
    const list = [...pending.values()].map(({ resolve, ev, ...p }) => ({
      ...p, tool: ev.tool_name, input: ev.tool_input, waiting: Math.round((Date.now() - p.since) / 1000),
    }));
    res.setHeader("content-type", "application/json");
    return res.end(JSON.stringify({ pending: list, log: readFileSync(LOG, "utf8").split("\n").slice(-40).join("\n") }));
  }

  // POST /answer/:id  {"action":"allow"|"deny"|"pass","text":"..."}
  if (req.method === "POST" && parts[0] === "answer") {
    const answer = JSON.parse((await readBody(req)) || "{}");
    const ids = parts[1] === "latest" ? [...pending.keys()].slice(-1) : [parts[1]];
    const p = pending.get(ids[0]);
    if (!p) { res.statusCode = 404; return res.end("no such pending request\n"); }
    p.resolve(answer);
    return res.end("ok\n");
  }

  // POST /hook/:agent[/permission|/question]
  if (req.method === "POST" && parts[0] === "hook") {
    const agent = parts[1];
    const kind = parts[2]; // undefined = status only
    const raw = await readBody(req);
    let ev = {};
    try { ev = JSON.parse(raw); } catch { log({ src: `hook:${agent}`, event: "BAD_JSON", note: raw.slice(0, 200) }); }
    log({ ...summarize(agent, ev), kind, tmuxPane: req.headers["x-tmux-pane"], herdrPane: req.headers["x-herdr-pane"], raw: ev });

    // The user answered in the terminal: the agent moves on but never closes the held hook.
    // Any later event from the same session means the held request is stale.
    if (/^(PostToolUse|PostToolUseFailure|Stop|UserPromptSubmit|Interrupt|SessionEnd)$/.test(ev.hook_event_name ?? "")) {
      for (const p of pending.values()) {
        if (p.ev.session_id === ev.session_id) {
          log({ src: "server", event: "STALE", tool: p.ev.tool_name, note: `id=${p.id} answered in the terminal` });
          p.resolve({ action: "pass" });
        }
      }
    }

    // Codex logs every PreToolUse; only hold it for question-like tools.
    const isQuestion = kind === "question" || (agent === "codex" && /request_user_input|ask/i.test(ev.tool_name ?? ""));
    const hold = kind === "permission" || (isQuestion && ev.hook_event_name === "PreToolUse");
    if (!hold) return res.end(agent === "codex" ? "{}" : "");

    const id = randomUUID().slice(0, 8);
    const holdKind = isQuestion ? "question" : "permission";
    const answer = await new Promise((resolve) => {
      pending.set(id, { id, agent, kind: holdKind, ev, resolve, since: Date.now() });
      log({ src: "server", event: "HOLDING", tool: ev.tool_name, note: `id=${id} answer: curl -XPOST localhost:${PORT}/answer/${id} -d '{"action":"allow"}'` });
      setTimeout(() => resolve({ action: "pass" }), HOLD_MS);
      // The agent closes the connection when the user answers in the terminal instead.
      res.on("close", () => {
        if (!res.writableFinished && pending.has(id)) {
          log({ src: "server", event: "CANCELLED", tool: ev.tool_name, note: `id=${id} agent closed the held hook` });
          resolve({ action: "cancelled" });
        }
      });
    });
    pending.delete(id);
    if (answer.action === "cancelled") return;
    const body = reply(agent, holdKind, ev, answer);
    log({ src: "server", event: "ANSWERED", tool: ev.tool_name, note: `id=${id} ${answer.action} -> ${body || "(empty body)"}` });
    return res.end(body);
  }

  res.statusCode = 404;
  res.end();
}).listen(PORT, "127.0.0.1", () => console.log(`Hook PoC on http://127.0.0.1:${PORT}  log: ${LOG}`));

// Cross-check: `claude agents --json`, logged only when a session's status changes.
const FILTER = process.env.AGENTS_CWD_FILTER ?? "";
const last = new Map();
setInterval(() => {
  execFile("claude", ["agents", "--json"], { timeout: 5000 }, (err, out) => {
    if (err) return;
    let list = [];
    try { list = JSON.parse(out); } catch { return; }
    for (const s of Array.isArray(list) ? list : list.sessions ?? []) {
      if (FILTER && !s.cwd?.startsWith(FILTER)) continue;
      const key = s.sessionId ?? String(s.pid);
      const state = `${s.status ?? s.state}${s.waitingFor ? ` (${s.waitingFor})` : ""}`;
      if (last.get(key) !== state) {
        last.set(key, state);
        log({ src: "claude-agents", event: "STATUS", session: key.slice(0, 8), note: state });
      }
    }
  });
}, 1500);
