{
  "name": "planesight",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Air traffic control for parallel coding agents running in Herdr",
  "scripts": {
    "start": "node server/server.mjs"
  },
  "dependencies": {
    "@google/genai": "2.28.0"
  }
}

// Minimal client for the Herdr socket API: one newline-delimited JSON request per connection.
import net from "node:net";
import os from "node:os";
import path from "node:path";

const SOCK = process.env.HERDR_SOCKET_PATH ?? path.join(os.homedir(), ".config/herdr/herdr.sock");
let seq = 0;

export function herdr(method, params = {}, timeoutMs = 5000) {
  return new Promise((resolve, reject) => {
    const id = `planesight:${++seq}`;
    const sock = net.createConnection(SOCK);
    let buf = "";
    const timer = setTimeout(() => {
      sock.destroy();
      reject(new Error(`herdr ${method} timed out`));
    }, timeoutMs);
    sock.on("connect", () => sock.write(JSON.stringify({ id, method, params }) + "\n"));
    sock.on("data", (chunk) => {
      buf += chunk;
      const nl = buf.indexOf("\n");
      if (nl < 0) return;
      clearTimeout(timer);
      sock.end();
      let msg;
      try { msg = JSON.parse(buf.slice(0, nl)); } catch (e) { return reject(e); }
      if (msg.error) return reject(Object.assign(new Error(`herdr ${method}: ${msg.error.message}`), { code: msg.error.code }));
      resolve(msg.result);
    });
    sock.on("error", (e) => {
      clearTimeout(timer);
      reject(e);
    });
  });
}

export const listAgents = async () => (await herdr("agent.list")).agents ?? [];
export const prompt = (target, text) => herdr("agent.prompt", { target, text });
export const sendKeys = (target, keys) => herdr("agent.send_keys", { target, keys });
export const focus = (target) => herdr("agent.focus", { target });
export async function readPane(paneId, lines = 60) {
  const r = await herdr("pane.read", { pane_id: paneId, source: "recent", lines, strip_ansi: true });
  return r?.read?.text ?? r?.text ?? "";
}

// Reads Entire's record of an agent session: files touched, tokens, last prompt.
import { execFile } from "node:child_process";

export function sessionInfo(sessionId, cwd) {
  return new Promise((resolve) => {
    execFile("entire", ["session", "info", sessionId, "--json"], { cwd, timeout: 8000 }, (err, out) => {
      if (err) return resolve(null);
      try { resolve(JSON.parse(out)); } catch { resolve(null); }
    });
  });
}

// The control tower: Gemini writes one card per item that needs the user, and ranks the queue.
// Without GEMINI_API_KEY both calls fall back to simple heuristics so the UI still works.
import { GoogleGenAI } from "@google/genai";

const MODEL = process.env.PLANESIGHT_MODEL ?? "gemini-3.8-flash";
const RANK_MODEL = process.env.PLANESIGHT_RANK_MODEL ?? MODEL;
const client = process.env.GEMINI_API_KEY ? new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY }) : null;

export const geminiEnabled = () => client !== null;
export const status = { lastError: null, calls: 0 };

async function json(model, system, input, schema) {
  status.calls++;
  const interaction = await client.interactions.create({
    model,
    system_instruction: system,
    input: JSON.stringify(input),
    response_format: { type: "text", mime_type: "application/json", schema },
  });
  return JSON.parse(interaction.output_text);
}

const CARD_SCHEMA = {
  type: "object",
  properties: {
    title: { type: "string", description: "3 to 6 words naming what the agent works on" },
    summary: { type: "string", description: "At most 2 short sentences: what the agent did and what it needs now" },
    category: { type: "string", enum: ["tool_approval", "design_decision", "clarification", "review", "error", "collision"] },
    proposal: {
      type: "object",
      properties: {
        action: { type: "string", enum: ["allow", "deny", "answer", "prompt", "dismiss"] },
        text: { type: "string", description: "Deny reason, answer, or next prompt. Empty for allow and dismiss." },
      },
      required: ["action", "text"],
    },
    reasoning: { type: "string", description: "One line: why this proposal" },
    effort_seconds: { type: "integer", description: "How long the user needs to check and accept this" },
    risk: { type: "string", enum: ["low", "medium", "high"] },
  },
  required: ["title", "summary", "category", "proposal", "reasoning", "effort_seconds", "risk"],
};

const CARD_SYSTEM = `You are the control tower of Plane Sight. A developer runs many coding agents in parallel.
One agent needs the developer. Write a short decision card so the developer can decide in seconds.

Allowed proposal actions by kind:
- approval (the agent asks to run a tool): "allow", or "deny" with a reason the agent will read.
- question (the agent asks the user a question): "answer" with the exact option label to pick, or "deny" with a free-text answer.
- blocked (a prompt is on the agent's screen; you only see the terminal text): "allow" or "deny" with a reason.
- landed (the agent finished its turn): "prompt" with the next instruction, or "dismiss" if nothing is left to do.

Rules:
- Propose "deny" for destructive or irreversible actions (deleting data, force pushes, publishing, spending money) and set risk "high".
- If a collision is reported, use category "collision" and propose "deny" with this wording:
  "The user denied this from their dashboard. Another agent is editing <file> right now. Do not retry. Stop and wait for the user."
- For a landed agent, a good next prompt is concrete: run the tests, fix what the agent itself flagged, or open a PR.
- Be specific. Name files and commands. No filler.`;

export async function writeCard(item) {
  if (!client) return fallbackCard(item);
  try {
    return await json(MODEL, CARD_SYSTEM, item, CARD_SCHEMA);
  } catch (e) {
    status.lastError = `card: ${e.message}`;
    return fallbackCard(item);
  }
}

function fallbackCard(item) {
  const tool = item.request?.tool ?? "";
  const base = {
    title: item.title ?? item.repo,
    effort_seconds: 10,
    risk: "low",
    reasoning: "Heuristic card (Gemini is not configured).",
  };
  if (item.collision) {
    return { ...base, category: "collision", risk: "high", summary: `Wants to edit ${item.collision.file}, which ${item.collision.other} is editing.`,
      proposal: { action: "deny", text: `The user denied this from their dashboard. Another agent is editing ${item.collision.file} right now. Do not retry. Stop and wait for the user.` } };
  }
  if (item.kind === "question") {
    const first = item.request?.input?.questions?.[0];
    return { ...base, category: "clarification", summary: first?.question ?? "The agent asks a question.",
      proposal: { action: "answer", text: first?.options?.[0]?.label ?? "" } };
  }
  if (item.kind === "landed") {
    return { ...base, category: "review", summary: (item.last_message ?? "The agent finished its turn.").slice(0, 200),
      proposal: { action: "dismiss", text: "" } };
  }
  return { ...base, category: "tool_approval", summary: `Wants to run ${tool || "a tool"}.`, proposal: { action: "allow", text: "" } };
}

const RANK_SCHEMA = {
  type: "object",
  properties: {
    order: {
      type: "array",
      items: {
        type: "object",
        properties: { key: { type: "string" }, reason: { type: "string", description: "At most 8 words" } },
        required: ["key", "reason"],
      },
    },
  },
  required: ["order"],
};

const RANK_SYSTEM = `You are the control tower of Plane Sight. Order the waiting agents so the developer unblocks
the most work per second of attention:
1. Collisions first, because two agents are about to overwrite each other.
2. Quick, low-risk approvals next, because each one sends an agent back to work in seconds.
3. Then decisions and questions that unblock other work.
4. Then reviews of agents that finished.
Longer waits break ties. The developer's recent decisions show their preferences: if they keep skipping
a kind of item or a repository, rank it lower; if they act on something fast, rank similar items higher.
Return every key exactly once.`;

export async function rank(items, decisions) {
  const fallback = fallbackRank(items);
  if (!client || items.length < 2) return fallback;
  try {
    const { order } = await json(RANK_MODEL, RANK_SYSTEM, { items, recent_decisions: decisions }, RANK_SCHEMA);
    const known = new Set(items.map((i) => i.key));
    const seen = new Set();
    const ranked = order.filter((o) => known.has(o.key) && !seen.has(o.key) && seen.add(o.key));
    // Anything Gemini dropped goes to the end in fallback order.
    return [...ranked, ...fallback.filter((f) => !seen.has(f.key))];
  } catch (e) {
    status.lastError = `rank: ${e.message}`;
    return fallback;
  }
}

function fallbackRank(items) {
  const weight = (i) => (i.collision ? -1 : { approval: 0, blocked: 0.5, question: 1, landed: 2 }[i.kind] ?? 3);
  return [...items]
    .sort((a, b) => weight(a) - weight(b) || b.waiting_seconds - a.waiting_seconds)
    .map((i) => ({ key: i.key, reason: i.collision ? "Collision" : i.kind === "landed" ? "Ready for review" : "Quick unblock" }));
}

// Plane Sight server. Holds agent approvals and questions from Claude Code and Codex hooks,
// polls Herdr for agent state, asks Gemini for a card per waiting item and a ranking,
// and pushes the whole state to the browser over Server-Sent Events.
import http from "node:http";
import path from "node:path";
import { execFile } from "node:child_process";
import { appendFileSync, mkdirSync, readFileSync, existsSync } from "node:fs";
import { randomUUID } from "node:crypto";
import * as h from "./herdr.mjs";
import * as gemini from "./gemini.mjs";
import { sessionInfo } from "./entire.mjs";

const PORT = Number(process.env.PORT ?? 7777);
const ROOT = new URL("..", import.meta.url).pathname;
const WEB = path.join(ROOT, "web");
const DATA = path.join(ROOT, "data");
const DECISIONS = path.join(DATA, "decisions.jsonl");
const CODEX_HOLD_MS = Number(process.env.CODEX_HOLD_MS ?? 60_000); // Codex blocks its terminal while held
const CLAUDE_HOLD_MS = Number(process.env.CLAUDE_HOLD_MS ?? 3_590_000); // just under the hook timeout
// Only show agents whose cwd starts with one of these prefixes (comma separated). Empty = all.
const ONLY = (process.env.PLANESIGHT_ONLY ?? "").split(",").filter(Boolean);
mkdirSync(DATA, { recursive: true });

// ---------------------------------------------------------------- state

/** sessionId -> unit. A unit is one agent session (one plane). */
const units = new Map();
const cards = new Map(); // need key -> card | "pending"
let ranking = []; // [{ key, reason }]
const repoCache = new Map(); // cwd -> repo name

function unit(sessionId) {
  let u = units.get(sessionId);
  if (!u) {
    u = { sessionId, paneId: null, agent: "agent", name: null, title: null, cwd: null, repo: null,
      status: "unknown", statusSince: Date.now(), held: null, landed: null, blockedAt: null,
      files: new Set(), lastPrompt: null, tokens: null, skipped: new Set() };
    units.set(sessionId, u);
  }
  return u;
}

function log(...args) {
  console.log(new Date().toISOString().slice(11, 19), ...args);
}

function repoOf(cwd) {
  if (!cwd) return Promise.resolve("unknown");
  if (repoCache.has(cwd)) return Promise.resolve(repoCache.get(cwd));
  return new Promise((resolve) => {
    execFile("git", ["-C", cwd, "rev-parse", "--path-format=absolute", "--git-common-dir"], (err, out) => {
      const name = err ? path.basename(cwd) : path.basename(path.dirname(out.trim()));
      repoCache.set(cwd, name);
      resolve(name);
    });
  });
}

const rel = (u, file) => (file && u.cwd ? path.relative(u.cwd, path.resolve(u.cwd, file)) : file);

// What the unit needs from the user right now, or null.
function needOf(u) {
  if (u.held) return { kind: u.held.kind, key: `held:${u.held.id}` };
  if (u.status === "blocked") return { kind: "blocked", key: `blocked:${u.sessionId}:${u.blockedAt}` };
  if (u.landed) return { kind: "landed", key: `landed:${u.sessionId}:${u.landed.at}` };
  return null;
}

// Another live session in the same repository already edited the file this request wants to write.
function collisionOf(u) {
  const file = u.held?.input?.file_path ?? u.held?.input?.path;
  if (!file || !/^(Write|Edit|MultiEdit|NotebookEdit)$/.test(u.held.tool ?? "")) return null;
  const target = rel(u, file);
  for (const o of units.values()) {
    if (o === u || o.repo !== u.repo || o.status === "gone") continue;
    if (o.files.has(target)) return { file: target, other: o.name ?? o.title ?? o.sessionId.slice(0, 8), otherSession: o.sessionId };
  }
  return null;
}

// ---------------------------------------------------------------- hooks

async function readBody(req) {
  let body = "";
  for await (const chunk of req) body += chunk;
  return body;
}

// Body for a held hook. `pass` means no decision: the agent falls back to its own terminal UI.
function hookReply(agent, kind, ev, answer) {
  if (answer.action === "pass") return agent === "codex" ? "{}" : "";
  if (kind === "question") {
    if (answer.action === "deny") {
      return JSON.stringify({ hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny",
        permissionDecisionReason: `The user already answered this question from the dashboard. Their answer: ${answer.text}` } });
    }
    const questions = ev.tool_input?.questions ?? [];
    const answers = Object.fromEntries(questions.map((q) => [q.question, answer.text || q.options?.[0]?.label || "yes"]));
    return JSON.stringify({ hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "allow",
      updatedInput: { ...ev.tool_input, answers } } });
  }
  const decision = answer.action === "allow"
    ? { behavior: "allow" }
    : { behavior: "deny", message: answer.text || "The user denied this from their dashboard." };
  return JSON.stringify({ hookSpecificOutput: { hookEventName: "PermissionRequest", decision } });
}

async function onHook(req, res, agent, kind) {
  let ev = {};
  try { ev = JSON.parse(await readBody(req)); } catch { return res.end(agent === "codex" ? "{}" : ""); }
  const name = ev.hook_event_name ?? "";
  if (!ev.session_id) return res.end(agent === "codex" ? "{}" : "");
  const u = unit(ev.session_id);
  u.agent = agent;
  u.paneId ??= req.headers["x-herdr-pane"] ?? null;
  if (ev.cwd && !u.cwd) { u.cwd = ev.cwd; u.repo = await repoOf(ev.cwd); }

  if (name === "UserPromptSubmit") { u.lastPrompt = ev.prompt ?? u.lastPrompt; u.landed = null; }
  if (/^(PostToolUse)$/.test(name)) {
    const file = ev.tool_input?.file_path ?? ev.tool_input?.path;
    if (file && /^(Write|Edit|MultiEdit|NotebookEdit)$/.test(ev.tool_name ?? "")) u.files.add(rel(u, file));
  }
  if (name === "Stop") u.landed = { at: Date.now(), message: ev.last_assistant_message ?? null };

  // The user answered in the terminal: the agent moves on but never closes the held hook.
  if (/^(PostToolUse|PostToolUseFailure|Stop|UserPromptSubmit|Interrupt|SessionEnd)$/.test(name) && u.held) {
    log("stale", u.held.tool, u.sessionId.slice(0, 8));
    u.held.resolve?.({ action: "pass" });
    u.held = null;
  }
  changed();

  const isQuestion = kind === "question" || (agent === "codex" && /request_user_input|ask/i.test(ev.tool_name ?? ""));
  const hold = kind === "permission" || (isQuestion && name === "PreToolUse");
  if (!hold) return res.end(agent === "codex" ? "{}" : "");

  const holdKind = isQuestion ? "question" : "approval";
  const id = randomUUID().slice(0, 8);
  const answer = await new Promise((resolve) => {
    u.held = { id, kind: holdKind, tool: ev.tool_name, input: ev.tool_input, since: Date.now(), resolve, expired: false };
    log("holding", holdKind, ev.tool_name, u.sessionId.slice(0, 8));
    changed();
    setTimeout(() => resolve({ action: "pass", timeout: true }), agent === "codex" ? CODEX_HOLD_MS : CLAUDE_HOLD_MS);
    res.on("close", () => { if (!res.writableFinished) resolve({ action: "cancelled" }); });
  });
  if (u.held?.id === id) {
    if (answer.timeout) {
      // Keep the request on screen. Answers now go through Herdr keys instead of the hook.
      u.held.expired = true;
      u.held.resolve = null;
    } else {
      u.held = null;
    }
    changed();
  }
  if (answer.action === "cancelled") return;
  res.end(hookReply(agent, holdKind, { tool_input: u.held?.input ?? {}, ...ev }, answer));
}

// ---------------------------------------------------------------- herdr polling

async function poll() {
  let agents;
  try { agents = await h.listAgents(); } catch (e) { log("herdr", e.message); return; }
  const seen = new Set();
  for (const a of agents) {
    const sessionId = a.agent_session?.value ?? `pane:${a.pane_id}`;
    const cwd = a.foreground_cwd ?? a.cwd;
    if (ONLY.length && !ONLY.some((p) => cwd?.startsWith(p))) continue;
    seen.add(sessionId);
    const u = unit(sessionId);
    u.paneId = a.pane_id;
    u.agent = a.agent ?? u.agent;
    u.name = a.name ?? u.name;
    u.title = a.terminal_title_stripped || u.title;
    if (!u.cwd) { u.cwd = cwd; u.repo = await repoOf(cwd); }
    const status = a.agent_status ?? "unknown";
    if (status !== u.status) {
      if (status === "blocked") u.blockedAt = Date.now();
      if (status === "done" && !u.landed) u.landed = { at: Date.now(), message: null };
      if (status === "working") { u.landed = null; if (u.held?.expired) u.held = null; }
      u.status = status;
      u.statusSince = Date.now();
      changed();
    }
  }
  for (const u of units.values()) {
    if (!seen.has(u.sessionId) && u.status !== "gone" && u.paneId && !u.held) {
      u.status = "gone";
      changed();
    }
  }
}

// ---------------------------------------------------------------- cards and ranking

async function itemFor(u, need) {
  const item = {
    key: need.key, kind: need.kind, agent: u.agent, repo: u.repo, title: u.title,
    waiting_seconds: Math.round((Date.now() - (u.held?.since ?? u.blockedAt ?? u.landed?.at ?? Date.now())) / 1000),
    last_user_prompt: u.lastPrompt?.slice(0, 600) ?? null,
  };
  if (u.held) item.request = { tool: u.held.tool, input: truncate(u.held.input) };
  const collision = collisionOf(u);
  if (collision) item.collision = collision;
  if (need.kind === "landed") {
    item.last_message = u.landed.message?.slice(0, 2000) ?? null;
    const info = await sessionInfo(u.sessionId, u.cwd);
    if (info) {
      u.tokens = info.tokens?.total ?? u.tokens;
      u.lastPrompt ??= info.last_prompt;
      item.entire = { files_touched: info.files_touched, turns: info.turns, tokens: info.tokens?.total, last_prompt: info.last_prompt };
    }
  }
  if (need.kind === "blocked" || (need.kind === "landed" && !item.last_message)) {
    item.terminal = await h.readPane(u.paneId, 40).catch(() => "");
  }
  return item;
}

function truncate(v) {
  const s = JSON.stringify(v ?? {});
  return s.length > 3000 ? s.slice(0, 3000) + "…" : v;
}

function fetchCards() {
  for (const u of units.values()) {
    const need = needOf(u);
    if (!need || cards.has(need.key)) continue;
    cards.set(need.key, "pending");
    itemFor(u, need)
      .then((item) => gemini.writeCard(item).then((card) => ({ ...card, collision: item.collision ?? null })))
      .then((card) => { cards.set(need.key, card); log("card", need.kind, card.proposal?.action, u.sessionId.slice(0, 8)); changed(); })
      .catch((e) => { cards.delete(need.key); log("card failed", e.message); });
  }
}

function queueItems() {
  const out = [];
  for (const u of units.values()) {
    const need = needOf(u);
    if (!need || u.skipped.has(need.key) || u.status === "gone") continue;
    const card = cards.get(need.key);
    out.push({ key: need.key, kind: need.kind, repo: u.repo, agent: u.agent,
      waiting_seconds: Math.round((Date.now() - (u.held?.since ?? u.blockedAt ?? u.landed?.at ?? Date.now())) / 1000),
      collision: collisionOf(u),
      card: card && card !== "pending" ? { category: card.category, summary: card.summary, effort_seconds: card.effort_seconds, risk: card.risk } : null });
  }
  return out;
}

let rankTimer = null;
let lastRankSig = "";
function scheduleRank() {
  clearTimeout(rankTimer);
  rankTimer = setTimeout(async () => {
    const items = queueItems();
    const sig = items.map((i) => `${i.key}:${i.card ? 1 : 0}:${i.collision ? 1 : 0}`).sort().join("|");
    if (sig === lastRankSig) return;
    lastRankSig = sig;
    ranking = await gemini.rank(items, recentDecisions());
    log("ranked", ranking.map((r) => r.key.split(":")[0]).join(" "));
    broadcast();
  }, 1200);
}

// ---------------------------------------------------------------- decisions

function recentDecisions(n = 20) {
  if (!existsSync(DECISIONS)) return [];
  return readFileSync(DECISIONS, "utf8").trim().split("\n").filter(Boolean).slice(-n).map((l) => JSON.parse(l));
}

async function answer(sessionId, { choice, action, text }) {
  const u = units.get(sessionId);
  const need = u && needOf(u);
  if (!need) throw new Error("nothing to answer");
  const card = cards.get(need.key);
  if (choice === "skip") {
    u.skipped.add(need.key);
  } else {
    action ??= card?.proposal?.action;
    text ??= card?.proposal?.text ?? "";
    await execute(u, need, action, text);
  }
  appendFileSync(DECISIONS, JSON.stringify({ t: new Date().toISOString(), choice, kind: need.kind, category: card?.category,
    repo: u.repo, agent: u.agent, action, proposed: card?.proposal?.action,
    waited_seconds: Math.round((Date.now() - (u.held?.since ?? u.blockedAt ?? u.landed?.at ?? Date.now())) / 1000) }) + "\n");
  log("answered", choice, action, u.sessionId.slice(0, 8));
  changed();
}

async function execute(u, need, action, text) {
  const target = u.paneId;
  if (u.held && !u.held.expired) {
    const hookAction = action === "allow" || action === "answer" ? "allow" : "deny";
    u.held.resolve({ action: hookAction, text });
    u.held = null;
    return;
  }
  if (need.kind === "landed") {
    if (action === "prompt" && text) await h.prompt(target, text);
    u.landed = null;
    return;
  }
  // A prompt on the agent's screen (expired hold, or an agent without our hooks).
  if (action === "allow" || action === "answer") {
    await h.sendKeys(target, ["enter"]);
  } else {
    await h.sendKeys(target, ["esc"]);
    if (text) setTimeout(() => h.prompt(target, text).catch((e) => log("prompt failed", e.message)), 1500);
  }
  u.held = null;
}

// ---------------------------------------------------------------- SSE

const clients = new Set();
let changeTimer = null;
function changed() {
  clearTimeout(changeTimer);
  changeTimer = setTimeout(() => { fetchCards(); scheduleRank(); broadcast(); }, 80);
}

function snapshot() {
  const order = new Map(ranking.map((r, i) => [r.key, i]));
  const planes = [...units.values()].filter((u) => u.status !== "gone").map((u) => {
    const need = needOf(u);
    const card = need ? cards.get(need.key) : null;
    return {
      session: u.sessionId, pane: u.paneId, agent: u.agent, name: u.name, title: u.title, repo: u.repo, status: u.status,
      tokens: u.tokens, files: [...u.files],
      need: need && { ...need, skipped: u.skipped.has(need.key), since: u.held?.since ?? u.blockedAt ?? u.landed?.at,
        rank: order.get(need.key) ?? null, reason: ranking.find((r) => r.key === need.key)?.reason ?? null,
        request: u.held ? { tool: u.held.tool, input: truncate(u.held.input), expired: u.held.expired } : null,
        message: u.landed?.message?.slice(0, 600) ?? null, collision: collisionOf(u),
        card: card === "pending" ? null : card ?? null, cardPending: card === "pending" },
    };
  });
  return { now: Date.now(), gemini: { enabled: gemini.geminiEnabled(), ...gemini.status }, planes };
}

function broadcast() {
  const data = `data: ${JSON.stringify(snapshot())}\n\n`;
  for (const res of clients) res.write(data);
}

// ---------------------------------------------------------------- http

const TYPES = { ".html": "text/html", ".js": "text/javascript", ".mjs": "text/javascript", ".css": "text/css", ".png": "image/png", ".json": "application/json", ".svg": "image/svg+xml" };

http.createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  const parts = url.pathname.split("/").filter(Boolean);
  try {
    if (req.method === "POST" && parts[0] === "hook") return await onHook(req, res, parts[1], parts[2]);

    if (req.method === "GET" && url.pathname === "/events") {
      res.writeHead(200, { "content-type": "text/event-stream", "cache-control": "no-cache", connection: "keep-alive" });
      clients.add(res);
      res.write(`data: ${JSON.stringify(snapshot())}\n\n`);
      req.on("close", () => clients.delete(res));
      return;
    }
    if (req.method === "POST" && parts[0] === "api" && parts[1] === "answer") {
      await answer(decodeURIComponent(parts[2]), JSON.parse((await readBody(req)) || "{}"));
      return res.end("ok");
    }
    if (req.method === "GET" && parts[0] === "api" && parts[1] === "tail") {
      const u = units.get(decodeURIComponent(parts[2]));
      return res.end(u?.paneId ? await h.readPane(u.paneId, 60) : "");
    }
    if (req.method === "POST" && parts[0] === "api" && parts[1] === "focus") {
      const u = units.get(decodeURIComponent(parts[2]));
      if (u?.paneId) await h.focus(u.paneId);
      return res.end("ok");
    }
    if (req.method === "GET") {
      const file = path.join(WEB, path.normalize(url.pathname === "/" ? "/index.html" : url.pathname));
      if (file.startsWith(WEB) && existsSync(file)) {
        res.setHeader("content-type", TYPES[path.extname(file)] ?? "application/octet-stream");
        return res.end(readFileSync(file));
      }
    }
    res.statusCode = 404;
    res.end();
  } catch (e) {
    log("error", req.url, e.message);
    res.statusCode = 500;
    res.end(e.message);
  }
}).listen(PORT, "127.0.0.1", () => {
  log(`Plane Sight on http://127.0.0.1:${PORT}  gemini=${gemini.geminiEnabled() ? "on" : "off (heuristics)"}`);
});

setInterval(poll, 1000);
poll();

