:root {
  --grass: #9db592;
  --tarmac: #5d6168;
  --paint: #f1eee4;
  --ink: #23272d;
  --ink-soft: #5b616b;
  --strip: #f4ecd6;
  --strip-edge: #d9ccaa;
  --bay: #2f3540;
  --bay-ink: #e7e3d8;
  --approval: #4f9a5e;
  --question: #d39a2c;
  --review: #4a7fbf;
  --alert: #c84b3a;
  --parked: #8b9098;
  --focus: #ffd35a;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  background: var(--bay);
  color: var(--ink);
  font: 16px/1.5 "Atkinson Hyperlegible", system-ui, sans-serif;
}

.layout {
  display: grid;
  grid-template-columns: 3fr 2fr;
  height: 100vh;
}

/* ---------------------------------------------------------------- airport */

.field {
  position: relative;
  background: var(--grass);
  min-width: 0;
  display: flex;
  flex-direction: column;
}
.field-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 14px 20px 0;
}
h1 {
  margin: 0;
  font: 600 28px/1 "Pixelify Sans", monospace;
  color: var(--ink);
  letter-spacing: .5px;
}
.tower { margin: 0; font-size: 14px; color: var(--ink-soft); }
.tower[data-on="true"]::before {
  content: "";
  display: inline-block;
  width: 8px; height: 8px;
  margin-right: 8px;
  background: var(--approval);
}
#airport { flex: 1; min-height: 0; }
#airport canvas { display: block; image-rendering: pixelated; }

/* ---------------------------------------------------------------- strip bay */

.bay {
  background: var(--bay);
  color: var(--bay-ink);
  padding: 20px 20px 12px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.bay-title {
  margin: 8px 0 0;
  font: 400 18px/1 "Pixelify Sans", monospace;
  color: var(--bay-ink);
}

.strip {
  --band: var(--parked);
  position: relative;
  background: var(--strip);
  color: var(--ink);
  border: 1px solid var(--strip-edge);
  border-left: 14px solid var(--band);
  padding: 16px 18px 16px 18px;
}
.strip[data-tone="approval"] { --band: var(--approval); }
.strip[data-tone="question"] { --band: var(--question); }
.strip[data-tone="review"] { --band: var(--review); }
.strip[data-tone="alert"] { --band: var(--alert); }

.callsign {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin: 0 0 2px;
}
.callsign strong { font: 600 24px/1.1 "Pixelify Sans", monospace; }
.callsign span { color: var(--ink-soft); font-size: 14px; }
.waited { margin-left: auto; font-size: 14px; color: var(--ink-soft); white-space: nowrap; }
.kindline { margin: 0 0 10px; font-size: 14px; color: var(--ink-soft); }

.summary { margin: 0 0 14px; font-size: 18px; line-height: 1.45; max-width: 60ch; }

.collision {
  margin: 0 0 14px;
  padding: 10px 12px;
  background: #f7d9d2;
  border-left: 4px solid var(--alert);
  font-size: 15px;
}

.proposal {
  border-top: 2px dashed var(--strip-edge);
  padding-top: 12px;
}
.proposal h3 { margin: 0 0 4px; font-size: 15px; font-weight: 700; }
.proposal p { margin: 0 0 6px; }
.proposal .text { white-space: pre-wrap; font-size: 16px; }
.proposal .why { color: var(--ink-soft); font-size: 14px; font-style: italic; }
.proposal textarea {
  width: 100%;
  min-height: 84px;
  font: inherit;
  padding: 8px 10px;
  border: 2px solid var(--ink);
  background: #fffaf0;
  resize: vertical;
}

.actions { display: flex; gap: 8px; margin-top: 14px; flex-wrap: wrap; }
button {
  font: 700 15px/1 "Atkinson Hyperlegible", system-ui, sans-serif;
  padding: 10px 14px;
  border: 2px solid var(--ink);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}
button.primary { background: var(--ink); color: var(--strip); }
button:hover { background: #e9dfc2; }
button.primary:hover { background: #3a4049; }
button:focus-visible, .queue button:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
button kbd { font: inherit; opacity: .6; margin-left: 6px; font-weight: 400; }

details.tail { margin-top: 14px; font-size: 14px; }
details.tail summary { cursor: pointer; color: var(--ink-soft); }
details.tail pre {
  margin: 8px 0 0;
  padding: 10px;
  max-height: 240px;
  overflow: auto;
  background: #23272d;
  color: #d9d6cc;
  font: 12px/1.4 ui-monospace, Menlo, monospace;
  white-space: pre-wrap;
}

.empty {
  background: transparent;
  border: 1px dashed #59606d;
  border-left-width: 1px;
  color: var(--bay-ink);
  padding: 28px 22px;
}
.empty strong { font: 600 22px/1.2 "Pixelify Sans", monospace; display: block; margin-bottom: 6px; }
.empty p { margin: 0; color: #b9b5aa; }

/* compact strips in the queue */
.queue { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.queue button {
  all: unset;
  box-sizing: border-box;
  display: grid;
  grid-template-columns: 26px 1fr auto;
  gap: 10px;
  align-items: baseline;
  width: 100%;
  padding: 8px 12px 8px 10px;
  background: #3a414d;
  border-left: 8px solid var(--band, var(--parked));
  cursor: pointer;
  color: var(--bay-ink);
}
.queue button:hover { background: #444c5a; }
.queue button[aria-current="true"] { background: #4b5361; }
.queue .pos { font: 400 16px/1 "Pixelify Sans", monospace; color: #b9b5aa; }
.queue .name { font-weight: 700; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.queue .line { grid-column: 2 / 4; font-size: 14px; color: #c9c5ba; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.queue .wait { font-size: 13px; color: #b9b5aa; }
.queue [data-tone="approval"] { --band: var(--approval); }
.queue [data-tone="question"] { --band: var(--question); }
.queue [data-tone="review"] { --band: var(--review); }
.queue [data-tone="alert"] { --band: var(--alert); }

.keys { margin: auto 0 0; padding-top: 12px; font-size: 13px; color: #9ea3ab; }
.keys kbd {
  font: 12px/1 "Atkinson Hyperlegible", sans-serif;
  border: 1px solid #6b717c;
  padding: 2px 5px;
  margin: 0 4px 0 10px;
}
.keys kbd:first-child { margin-left: 0; }

@media (max-width: 900px) {
  .layout { grid-template-columns: 1fr; grid-template-rows: 45vh auto; height: auto; }
}
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

// The airport: a calm top-down apron in Phaser 4.
// Taxiway = ranked queue (#1 at the hold line), gates = repositories, the field below = agents in flight.
// Motion happens only when something changes; the #1 plane breathes slowly.

const W = 960;
const H = 600;
const C = {
  grass: 0x9db592, grassDark: 0x8fa885, tarmac: 0x5d6168, apron: 0x6b7077, runway: 0x4c5057,
  paint: 0xf1eee4, yellow: 0xe6c34a, building: 0xcfc6b2, roof: 0xb7ad97, ink: 0x23272d,
};
const TONES = { approval: "#4f9a5e", question: "#d39a2c", review: "#4a7fbf", alert: "#c84b3a", parked: "#8b9098", flight: "#e7e3d8" };
const TAXI_Y = 400;
const HOLD_X = 800;
const SLOT = 84;
const MAX_SLOTS = 8;
const GATE_Y = 168;
const FLIGHT = { x0: 70, x1: 740, y0: 500, y1: 565 };

// 18 x 12 pixel plane, nose to the right. o = body, # = outline, w = cockpit.
const PLANE = [
  "........##........",
  "........#o#.......",
  "........#oo#......",
  "##......#ooo#.....",
  "#o######ooooo####.",
  "#oooooooooooooow#.",
  "#oooooooooooooooo#",
  "#o######ooooo####.",
  "##......#ooo#.....",
  "........#oo#......",
  "........#o#.......",
  "........##........",
];

function planeTexture(scene, key, body, outline = "#2a2e35") {
  if (scene.textures.exists(key)) return;
  const tex = scene.textures.createCanvas(key, PLANE[0].length, PLANE.length);
  const ctx = tex.getContext();
  PLANE.forEach((row, y) => [...row].forEach((ch, x) => {
    if (ch === ".") return;
    ctx.fillStyle = ch === "o" ? body : ch === "w" ? "#dfe9f2" : outline;
    ctx.fillRect(x, y, 1, 1);
  }));
  tex.refresh();
}

class AirportScene extends Phaser.Scene {
  constructor(hooks) {
    super("airport");
    this.hooks = hooks;
    this.planes = new Map(); // session -> container
    this.gateKey = "";
    this.model = null;
  }

  create() {
    for (const [tone, color] of Object.entries(TONES)) planeTexture(this, `plane-${tone}`, color);
    planeTexture(this, "plane-shadow", "rgba(0,0,0,.22)", "rgba(0,0,0,.22)");
    this.drawField();
    this.gateLayer = this.add.container(0, 0);
    this.select = this.add.graphics().setDepth(5);
    this.overflow = this.add.text(48, TAXI_Y - 46, "", this.font(14, "#f1eee4"));
    this.flightLabel = this.add.text(FLIGHT.x0 - 22, FLIGHT.y0 - 34, "", this.font(16, "#23272d"));
    if (this.model) this.apply(this.model);
  }

  font(size, color) {
    return { fontFamily: '"Pixelify Sans", monospace', fontSize: `${size}px`, color, resolution: 2 };
  }

  drawField() {
    const g = this.add.graphics();
    // grass texture: a few darker tufts on a fixed grid, no randomness between renders
    g.fillStyle(C.grass).fillRect(0, 0, W, H);
    g.fillStyle(C.grassDark);
    for (let y = 12; y < H; y += 36) for (let x = (y / 36) % 2 ? 20 : 2; x < W; x += 44) g.fillRect(x, y, 4, 2);
    // terminal building and apron
    g.fillStyle(C.apron).fillRect(30, 124, 770, 150);
    g.fillStyle(C.roof).fillRect(30, 70, 770, 54);
    g.fillStyle(C.building).fillRect(36, 76, 758, 42);
    // taxiway with centre line, and the connector to the apron
    g.fillStyle(C.tarmac).fillRect(0, TAXI_Y - 30, HOLD_X + 60, 60);
    g.fillStyle(C.tarmac).fillRect(380, 274, 70, TAXI_Y - 274);
    g.fillStyle(C.yellow);
    for (let x = 6; x < HOLD_X; x += 28) g.fillRect(x, TAXI_Y - 1, 14, 3);
    for (let y = 280; y < TAXI_Y - 30; y += 24) g.fillRect(414, y, 3, 12);
    // hold-short line
    g.fillRect(HOLD_X + 14, TAXI_Y - 30, 3, 60);
    g.fillRect(HOLD_X + 20, TAXI_Y - 30, 3, 60);
    // runway
    g.fillStyle(C.runway).fillRect(850, 0, 70, H);
    g.fillStyle(C.paint);
    for (let y = 20; y < H; y += 48) g.fillRect(883, y, 4, 24);
    for (let x = 856; x < 916; x += 10) g.fillRect(x, H - 34, 6, 22);
    this.add.text(872, H - 70, "27", this.font(18, "#f1eee4"));
    // flight field outline
    g.lineStyle(2, C.grassDark).strokeRect(FLIGHT.x0 - 30, FLIGHT.y0 - 42, FLIGHT.x1 - FLIGHT.x0 + 60, FLIGHT.y1 - FLIGHT.y0 + 72);
    this.add.text(W - 236, 300, "", this.font(14, "#23272d"));
  }

  drawGates(repos) {
    const key = repos.join("|");
    if (key === this.gateKey) return;
    this.gateKey = key;
    this.gateLayer.removeAll(true);
    this.gates = new Map();
    const n = Math.max(repos.length, 1);
    const width = 758 / n;
    repos.forEach((repo, i) => {
      const x = 36 + i * width;
      const g = this.add.graphics();
      if (i > 0) g.fillStyle(C.roof).fillRect(x - 2, 76, 4, 42);
      g.fillStyle(C.paint).fillRect(x + width / 2 - 1, 124, 2, 22);
      const label = this.add.text(x + 12, 86, repo.length > 18 ? repo.slice(0, 17) + "…" : repo, this.font(18, "#23272d"));
      this.gateLayer.add([g, label]);
      this.gates.set(repo, { x, width });
    });
  }

  // Where every plane should be, given the model.
  layout(model) {
    const targets = new Map();
    model.queue.slice(0, MAX_SLOTS).forEach((p, i) => {
      targets.set(p.session, { x: HOLD_X - 30 - i * SLOT, y: TAXI_Y, scale: 3, alpha: 1, tone: p.tone, label: p.label, rank: i, shadow: 0 });
    });
    this.overflow.setText(model.queue.length > MAX_SLOTS ? `+${model.queue.length - MAX_SLOTS} more waiting` : "");
    const perGate = new Map();
    for (const p of model.parked) {
      const gate = this.gates.get(p.repo);
      if (!gate) continue;
      const k = perGate.get(p.repo) ?? 0;
      perGate.set(p.repo, k + 1);
      const cols = Math.max(1, Math.floor((gate.width - 20) / 50));
      targets.set(p.session, { x: gate.x + 34 + (k % cols) * 50, y: GATE_Y + Math.floor(k / cols) * 44, scale: 2, alpha: 0.9, tone: p.tone, label: p.label, rank: null, shadow: 0, small: true });
    }
    const n = model.inFlight.length;
    model.inFlight.forEach((p, i) => {
      const cols = Math.min(n, 9);
      const x = FLIGHT.x0 + ((i % cols) + 0.5) * ((FLIGHT.x1 - FLIGHT.x0) / cols);
      const y = FLIGHT.y0 + Math.floor(i / cols) * 40 + (i % 2) * 12;
      targets.set(p.session, { x, y, scale: 2, alpha: 0.55, tone: "flight", label: "", rank: null, shadow: 6 });
    });
    this.flightLabel.setText(n ? `${n} in flight` : "Nothing in flight");
    return targets;
  }

  apply(model) {
    this.model = model;
    if (!this.sys?.isActive?.()) return;
    this.drawGates(model.repos);
    const targets = this.layout(model);

    for (const [session, t] of targets) {
      let c = this.planes.get(session);
      if (c?.takingOff) continue;
      if (!c) {
        c = this.makePlane(session, t);
        this.planes.set(session, c);
      }
      c.plane.setTexture(`plane-${t.tone}`);
      c.label.setText(t.label ?? "");
      c.label.setFontSize(t.small ? 12 : 14);
      c.shadow.setPosition(t.shadow, t.shadow);
      this.tweens.add({ targets: c, x: t.x, y: t.y, alpha: t.alpha, duration: 700, ease: "Sine.easeInOut" });
      this.tweens.add({ targets: c.body, scale: t.scale, duration: 700, ease: "Sine.easeInOut" });
      this.setPulse(c, t.rank === 0);
      c.target = t;
    }
    for (const [session, c] of this.planes) {
      if (targets.has(session) || c.takingOff) continue;
      this.planes.delete(session);
      this.tweens.add({ targets: c, alpha: 0, duration: 400, onComplete: () => c.destroy() });
    }
    this.drawSelection(model.selected);
  }

  makePlane(session, t) {
    const shadow = this.add.image(t.shadow, t.shadow, "plane-shadow");
    const plane = this.add.image(0, 0, `plane-${t.tone}`);
    const body = this.add.container(0, 0, [shadow, plane]).setScale(t.scale);
    const label = this.add.text(0, 24, "", this.font(14, "#f1eee4")).setOrigin(0.5, 0);
    // entering planes taxi in from the left end of the taxiway; others fade in where they are
    const startX = t.rank !== null ? -40 : t.x;
    const c = this.add.container(startX, t.y, [body, label]).setAlpha(t.rank !== null ? 1 : 0);
    Object.assign(c, { plane, shadow, body, label, session });
    c.setSize(60, 48).setInteractive({ useHandCursor: true });
    c.on("pointerdown", () => this.hooks.onSelect(session));
    return c;
  }

  setPulse(c, on) {
    if (on && !c.pulse) {
      c.pulse = this.tweens.add({ targets: c.plane, alpha: 0.55, duration: 1100, yoyo: true, repeat: -1, ease: "Sine.easeInOut" });
    } else if (!on && c.pulse) {
      c.pulse.stop();
      c.pulse = null;
      c.plane.setAlpha(1);
    }
  }

  drawSelection(session) {
    this.select.clear();
    const c = session && this.planes.get(session);
    if (!c?.target) return;
    const { x, y } = c.target;
    const s = c.target.scale === 3 ? 34 : 24;
    this.select.lineStyle(3, 0xffd35a);
    for (const [dx, dy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
      const cx = x + dx * s;
      const cy = y + dy * (s - 6);
      this.select.lineBetween(cx, cy, cx - dx * 10, cy);
      this.select.lineBetween(cx, cy, cx, cy - dy * 10);
    }
  }

  // The one orchestrated moment: taxi onto the runway, turn, climb out.
  takeoff(session) {
    const c = this.planes.get(session);
    if (!c || c.takingOff) return;
    c.takingOff = true;
    this.setPulse(c, false);
    this.select.clear();
    c.label.setText("");
    this.tweens.chain({
      targets: c,
      tweens: [
        { x: 885, y: TAXI_Y, duration: 600, ease: "Sine.easeIn" },
        { angle: -90, duration: 300, ease: "Sine.easeInOut" },
        { y: -60, duration: 1100, ease: "Quad.easeIn" },
      ],
      onComplete: () => { this.planes.delete(session); c.destroy(); },
    });
    this.tweens.add({ targets: c.shadow, x: 14, y: 14, delay: 900, duration: 900 });
    this.tweens.add({ targets: c.body, scale: 3.6, delay: 900, duration: 1100 });
  }
}

export function createAirport(parent, hooks) {
  const scene = new AirportScene(hooks);
  new Phaser.Game({
    type: Phaser.AUTO,
    parent,
    width: W,
    height: H,
    pixelArt: true,
    backgroundColor: "#9db592",
    scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },
    scene,
  });
  return {
    update: (model) => scene.apply(model),
    takeoff: (session) => scene.takeoff(session),
  };
}

