// Strip bay and wiring: live state from the server, the decision strip, keyboard control.
import { createAirport } from "./airport.js";

const $ = (id) => document.getElementById(id);
let state = { planes: [], gemini: {} };
let selected = null;
let editing = false;
let tailOpen = false;

const ACTIONS = {
  allow: { heading: "Proposed: approve", button: "Approve" },
  deny: { heading: "Proposed: deny and tell the agent why", button: "Deny" },
  answer: { heading: "Proposed answer", button: "Send answer" },
  prompt: { heading: "Proposed next prompt", button: "Send prompt" },
  dismiss: { heading: "Proposed: nothing more to do", button: "Mark reviewed" },
};
// Editing an approve turns it into a deny with your text; editing "mark reviewed" sends your text as a prompt.
const EDIT_ACTION = { allow: "deny", dismiss: "prompt" };

function tone(need) {
  if (!need) return "parked";
  const c = need.card?.category;
  if (need.collision || c === "collision" || c === "error") return "alert";
  if (c === "review" || need.kind === "landed") return "review";
  if (c === "design_decision" || c === "clarification" || need.kind === "question") return "question";
  return "approval";
}

const callsign = (p) => p.name ?? p.title?.split(" ").slice(0, 3).join(" ") ?? p.session.slice(0, 6);
const short = (s, n) => (s && s.length > n ? s.slice(0, n - 1) + "…" : s ?? "");

function waited(since) {
  if (!since) return "";
  const s = Math.max(0, Math.round((Date.now() - since) / 1000));
  if (s < 60) return `${s} s`;
  if (s < 3600) return `${Math.floor(s / 60)} min`;
  return `${Math.floor(s / 3600)} h ${Math.floor((s % 3600) / 60)} min`;
}

function whatItWants(p) {
  const n = p.need;
  const file = n.request?.input?.file_path ?? n.request?.input?.path;
  const cmd = n.request?.input?.command;
  if (n.kind === "approval") return `Asks to run ${n.request?.tool ?? "a tool"}${file ? ` on ${short(file.split("/").pop(), 40)}` : cmd ? `: ${short(cmd, 60)}` : ""}.`;
  if (n.kind === "question") return "Asks you a question.";
  if (n.kind === "landed") return "Finished its turn and waits for your review.";
  return "Waits at a prompt in its terminal.";
}

function queueOf(planes) {
  return planes
    .filter((p) => p.need && !p.need.skipped)
    .sort((a, b) => (a.need.rank ?? 999) - (b.need.rank ?? 999) || (a.need.since ?? 0) - (b.need.since ?? 0));
}

// ---------------------------------------------------------------- render

function render() {
  const queue = queueOf(state.planes);
  if (!queue.some((p) => p.session === selected)) { selected = queue[0]?.session ?? null; editing = false; tailOpen = false; }
  const active = queue.find((p) => p.session === selected);

  const tower = $("tower");
  tower.dataset.on = String(Boolean(state.gemini.enabled));
  tower.textContent = state.gemini.enabled ? "Tower: Gemini 3.8 Flash" : "Tower: simple rules (no Gemini key)";

  if (!editing) $("active").replaceChildren(active ? strip(active, queue.indexOf(active)) : emptyStrip());
  $("queue-title").textContent = queue.length > 1 ? `Holding (${queue.length})` : queue.length ? "Holding" : "";
  $("queue").replaceChildren(...queue.map((p, i) => queueRow(p, i)));

  airport.update({
    queue: queue.map((p) => ({ session: p.session, tone: tone(p.need), label: short(callsign(p), 12) })),
    parked: state.planes.filter((p) => (!p.need || p.need.skipped) && p.status !== "working").map((p) => ({ session: p.session, repo: p.repo, tone: tone(p.need) === "parked" ? "parked" : tone(p.need), label: short(callsign(p), 10) })),
    inFlight: state.planes.filter((p) => p.status === "working" && (!p.need || p.need.skipped)).map((p) => ({ session: p.session })),
    repos: [...new Set(state.planes.map((p) => p.repo).filter(Boolean))].sort(),
    selected,
  });
}

function el(tag, attrs = {}, ...children) {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k.startsWith("on")) e.addEventListener(k.slice(2), v);
    else if (k === "dataset") Object.assign(e.dataset, v);
    else if (v !== undefined && v !== null) e.setAttribute(k, v);
  }
  e.append(...children.flat().filter((c) => c !== null && c !== undefined && c !== false));
  return e;
}

function strip(p, index) {
  const n = p.need;
  const card = n.card;
  const action = card?.proposal?.action;
  const meta = ACTIONS[action] ?? ACTIONS.allow;
  const editAction = EDIT_ACTION[action] ?? action;

  const proposal = !card
    ? el("p", { class: "why" }, n.cardPending ? "The tower is reading this agent…" : "No proposal yet.")
    : editing
      ? [
          el("h3", {}, editAction === "deny" ? "Your reason for denying" : editAction === "prompt" ? "Your next prompt" : "Your answer"),
          el("textarea", { id: "edit", "aria-label": "Your text" }, card.proposal.text ?? ""),
        ]
      : [
          el("h3", {}, meta.heading),
          card.proposal.text ? el("p", { class: "text" }, card.proposal.text) : null,
          el("p", { class: "why" }, card.reasoning),
        ];

  const buttons = editing
    ? [
        el("button", { class: "primary", onclick: () => submitEdit(p, editAction) }, "Send", el("kbd", {}, "⌘⏎")),
        el("button", { onclick: () => { editing = false; render(); } }, "Cancel", el("kbd", {}, "Esc")),
      ]
    : [
        el("button", { class: "primary", disabled: card ? null : "", onclick: () => accept(p) }, meta.button, el("kbd", {}, "⏎")),
        el("button", { disabled: card ? null : "", onclick: () => startEdit() }, "Edit", el("kbd", {}, "E")),
        el("button", { onclick: () => skip(p) }, "Skip", el("kbd", {}, "S")),
      ];

  const tail = el("details", { class: "tail", ontoggle: (e) => toggleTail(p, e.target) }, el("summary", {}, "Terminal output"), el("pre", { id: "tail" }, "…"));
  if (tailOpen) { tail.open = true; loadTail(p, tail); }

  return el("article", { class: "strip", dataset: { tone: tone(n) }, "aria-label": `Next: ${callsign(p)}` },
    el("p", { class: "callsign" },
      el("strong", {}, callsign(p)),
      el("span", {}, `${p.repo ?? ""} ${p.agent ?? ""}`),
      el("span", { class: "waited", "data-since": n.since ?? "" }, `waiting ${waited(n.since)}`)),
    el("p", { class: "kindline" }, index === 0 ? whatItWants(p) : `#${index + 1} in line. ${whatItWants(p)}`),
    el("p", { class: "summary" }, card?.summary ?? (n.message ? short(n.message, 240) : "")),
    n.collision ? el("p", { class: "collision" }, `Collision: ${n.collision.other} already edited ${n.collision.file}.`) : null,
    el("div", { class: "proposal" }, proposal),
    el("div", { class: "actions" }, buttons, el("button", { onclick: () => post(`/api/focus/${p.session}`) }, "Open terminal")),
    tail,
  );
}

function emptyStrip() {
  const flying = state.planes.filter((p) => p.status === "working").length;
  return el("article", { class: "strip empty" },
    el("strong", {}, "All clear"),
    el("p", {}, flying ? `${flying} agents are working. Nothing needs you right now.` : "No agent needs you. Start agents in Herdr and they appear here."));
}

function queueRow(p, i) {
  return el("li", {}, el("button", { "aria-current": String(p.session === selected), dataset: { tone: tone(p.need) }, onclick: () => choose(p.session) },
    el("span", { class: "pos" }, String(i + 1)),
    el("span", { class: "name" }, callsign(p)),
    el("span", { class: "wait", "data-since": p.need.since ?? "" }, waited(p.need.since)),
    el("span", { class: "line" }, p.need.reason ? `${p.need.reason}. ${p.need.card?.summary ?? ""}` : p.need.card?.summary ?? whatItWants(p))));
}

// ---------------------------------------------------------------- actions

async function post(url, body) {
  const res = await fetch(url, { method: "POST", body: body ? JSON.stringify(body) : undefined });
  if (!res.ok) console.warn(url, await res.text());
  return res.ok;
}

async function accept(p) {
  if (!p.need.card) return;
  airport.takeoff(p.session);
  await post(`/api/answer/${p.session}`, { choice: "accept" });
}

function startEdit() {
  editing = true;
  render();
  $("active").replaceChildren(strip(queueOf(state.planes).find((p) => p.session === selected), 0));
  const t = $("edit");
  t?.focus();
  t?.setSelectionRange(t.value.length, t.value.length);
}

async function submitEdit(p, action) {
  const text = $("edit")?.value.trim() ?? "";
  editing = false;
  airport.takeoff(p.session);
  await post(`/api/answer/${p.session}`, { choice: "edit", action, text });
}

async function skip(p) {
  await post(`/api/answer/${p.session}`, { choice: "skip" });
}

function choose(session) {
  if (editing) return;
  selected = session;
  tailOpen = false;
  render();
}

async function loadTail(p, details) {
  const res = await fetch(`/api/tail/${p.session}`);
  const pre = details.querySelector("pre");
  pre.textContent = (await res.text()).trimEnd() || "(empty)";
  pre.scrollTop = pre.scrollHeight;
}

function toggleTail(p, details) {
  tailOpen = details.open;
  if (details.open) loadTail(p, details);
}

document.addEventListener("keydown", (e) => {
  const queue = queueOf(state.planes);
  const active = queue.find((p) => p.session === selected);
  if (editing) {
    if (e.key === "Escape") { editing = false; render(); }
    if (e.key === "Enter" && (e.metaKey || e.ctrlKey) && active) submitEdit(active, EDIT_ACTION[active.need.card?.proposal?.action] ?? active.need.card?.proposal?.action);
    return;
  }
  if (e.target.closest?.("button, summary") && e.key === "Enter") return;
  if (!active) return;
  const i = queue.indexOf(active);
  if (e.key === "Enter") { e.preventDefault(); accept(active); }
  else if (e.key === "e" || e.key === "E") { e.preventDefault(); startEdit(); }
  else if (e.key === "s" || e.key === "S") skip(active);
  else if (e.key === "ArrowDown" || e.key === "j") choose(queue[Math.min(i + 1, queue.length - 1)].session);
  else if (e.key === "ArrowUp" || e.key === "k") choose(queue[Math.max(i - 1, 0)].session);
});

// waiting times tick without re-rendering
setInterval(() => {
  for (const span of document.querySelectorAll("[data-since]")) {
    const since = Number(span.dataset.since);
    if (!since) continue;
    span.textContent = span.classList.contains("waited") ? `waiting ${waited(since)}` : waited(since);
  }
}, 1000);

// ---------------------------------------------------------------- boot

await document.fonts.load('16px "Pixelify Sans"').catch(() => {});
const airport = createAirport($("airport"), { onSelect: choose });

const events = new EventSource("/events");
events.onmessage = (e) => {
  state = JSON.parse(e.data);
  render();
};

