// Plane Sight's Tower: the agents that need you, ranked by Gemini, with the answer already drafted.
// State comes from the Plane Sight server (planesight/server), not from herdr-web-ui's bridge.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { PlaneTakeoff, SquareTerminal, TowerControl, TriangleAlert } from "lucide-react";
import { AgentMark } from "./AgentMark.tsx";
import "./TowerView.css";

const TOWER_URL = (import.meta.env.VITE_PLANESIGHT_URL as string | undefined) ?? "http://127.0.0.1:7777";

type Action = "allow" | "deny" | "answer" | "prompt" | "dismiss";
interface Card {
  title: string;
  summary: string;
  category: string;
  proposal: { action: Action; text: string };
  reasoning: string;
  effort_seconds: number;
  risk: "low" | "medium" | "high";
}
interface Need {
  kind: "approval" | "question" | "blocked" | "landed";
  key: string;
  skipped: boolean;
  since: number | null;
  rank: number | null;
  reason: string | null;
  request: { tool?: string; input?: Record<string, unknown>; expired: boolean } | null;
  message: string | null;
  collision: { file: string; other: string } | null;
  card: Card | null;
  cardPending: boolean;
}
interface Plane {
  session: string;
  pane: string | null;
  agent: string;
  name: string | null;
  title: string | null;
  repo: string | null;
  status: string;
  need: Need | null;
}
interface TowerState {
  gemini: { enabled: boolean; lastError: string | null };
  planes: Plane[];
}

const ACTIONS: Record<Action, { heading: string; button: string }> = {
  allow: { heading: "Proposed: approve", button: "Approve" },
  deny: { heading: "Proposed: deny and tell the agent why", button: "Deny" },
  answer: { heading: "Proposed answer", button: "Send answer" },
  prompt: { heading: "Proposed next prompt", button: "Send prompt" },
  dismiss: { heading: "Proposed: nothing more to do", button: "Mark reviewed" },
};
// Editing an approve turns it into a deny with your reason; editing "mark reviewed" sends your text as a prompt.
const EDIT_ACTION: Partial<Record<Action, Action>> = { allow: "deny", dismiss: "prompt" };

function tone(need: Need): "danger" | "input" | "question" | "review" {
  if (need.collision || need.card?.category === "collision" || need.card?.category === "error") return "danger";
  if (need.kind === "landed" || need.card?.category === "review") return "review";
  if (need.kind === "question" || need.card?.category === "design_decision" || need.card?.category === "clarification") return "question";
  return "input";
}
const TONE_WORD = { danger: "COLLISION", input: "APPROVE", question: "DECIDE", review: "REVIEW" };

const callsign = (p: Plane) => p.name ?? p.need?.card?.title ?? p.title ?? p.session.slice(0, 8);

function waited(since: number | null, now: number) {
  if (!since) return "";
  const s = Math.max(0, Math.round((now - since) / 1000));
  if (s < 60) return `${s} s`;
  if (s < 3600) return `${Math.floor(s / 60)} min`;
  return `${Math.floor(s / 3600)} h ${Math.floor((s % 3600) / 60)} min`;
}

function whatItWants(need: Need) {
  const input = need.request?.input ?? {};
  const file = (input.file_path ?? input.path) as string | undefined;
  const command = input.command as string | undefined;
  if (need.kind === "approval") {
    const target = file ? ` on ${file.split("/").pop()}` : command ? `: ${command.slice(0, 80)}` : "";
    return `Asks to run ${need.request?.tool ?? "a tool"}${target}.`;
  }
  if (need.kind === "question") return "Asks you a question.";
  if (need.kind === "landed") return "Finished its turn and waits for your review.";
  return "Waits at a prompt in its terminal.";
}

function rankOrder(a: Plane, b: Plane) {
  return (a.need!.rank ?? 999) - (b.need!.rank ?? 999) || (a.need!.since ?? 0) - (b.need!.since ?? 0);
}

export function TowerView({ onOpenPane }: { onOpenPane: (paneId: string) => void }) {
  const [state, setState] = useState<TowerState | null>(null);
  const [offline, setOffline] = useState(false);
  const [selected, setSelected] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState("");
  const [departing, setDeparting] = useState<Set<string>>(new Set());
  const [error, setError] = useState<string | null>(null);
  const [now, setNow] = useState(() => Date.now());
  const shownAt = useRef(0);
  const editRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const events = new EventSource(`${TOWER_URL}/events`);
    events.onmessage = (event) => { setState(JSON.parse(event.data) as TowerState); setOffline(false); };
    events.onerror = () => setOffline(true);
    return () => events.close();
  }, []);

  useEffect(() => {
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(timer);
  }, []);

  const planes = state?.planes ?? [];
  const queue = useMemo(() => planes.filter((p) => p.need && !p.need.skipped).sort(rankOrder), [planes]);
  const inFlight = planes.filter((p) => p.status === "working" && (!p.need || p.need.skipped));
  const active = queue.find((p) => p.session === selected) ?? queue[0] ?? null;
  const activeKey = active?.need?.key ?? null;

  useEffect(() => {
    shownAt.current = Date.now();
    setEditing(false);
    setError(null);
  }, [activeKey]);

  const answer = useCallback(async (plane: Plane, body: Record<string, unknown>) => {
    if (body.choice !== "skip") setDeparting((set) => new Set(set).add(plane.session));
    const res = await fetch(`${TOWER_URL}/api/answer/${encodeURIComponent(plane.session)}`, {
      method: "POST",
      body: JSON.stringify({ ...body, key: plane.need?.key }),
    }).catch(() => null);
    setDeparting((set) => { const next = new Set(set); next.delete(plane.session); return next; });
    if (!res?.ok) setError(res ? await res.text() : "The Plane Sight server does not answer.");
  }, []);

  const accept = useCallback((plane: Plane) => {
    if (!plane.need?.card) return;
    void answer(plane, { choice: "accept" });
  }, [answer]);

  const startEdit = useCallback((plane: Plane) => {
    if (!plane.need?.card) return;
    setDraft(plane.need.card.proposal.text ?? "");
    setEditing(true);
    window.setTimeout(() => editRef.current?.focus(), 0);
  }, []);

  const sendEdit = useCallback((plane: Plane) => {
    const action = plane.need?.card?.proposal.action;
    if (!action) return;
    setEditing(false);
    void answer(plane, { choice: "edit", action: EDIT_ACTION[action] ?? action, text: draft.trim() });
  }, [answer, draft]);

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      if (!active || event.metaKey && event.key !== "Enter") return;
      if (editing) {
        if (event.key === "Escape") setEditing(false);
        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) { event.preventDefault(); sendEdit(active); }
        return;
      }
      if (target?.closest("input, textarea, select, button, .xterm, [contenteditable]")) return;
      const index = queue.indexOf(active);
      if (event.key === "Enter") {
        event.preventDefault();
        // a strip that just appeared is read before it is answered
        if (!event.repeat && Date.now() - shownAt.current > 700) accept(active);
      } else if (event.key === "e" || event.key === "E") { event.preventDefault(); startEdit(active); }
      else if (event.key === "s" || event.key === "S") void answer(active, { choice: "skip" });
      else if (event.key === "ArrowDown" || event.key === "j") setSelected(queue[Math.min(index + 1, queue.length - 1)]?.session ?? null);
      else if (event.key === "ArrowUp" || event.key === "k") setSelected(queue[Math.max(index - 1, 0)]?.session ?? null);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [active, editing, queue, accept, startEdit, sendEdit, answer]);

  const waiting = queue.length;
  return (
    <section className="tower" aria-label="Tower">
      <header className="tower-head">
        <div className="tower-title">
          <TowerControl size={20} aria-hidden="true" />
          <h1>Tower</h1>
        </div>
        <p className="tower-counts" role="status">
          {offline ? "Plane Sight server offline" : `${waiting} ${waiting === 1 ? "agent needs" : "agents need"} you, ${inFlight.length} in flight`}
        </p>
        <span className={`tower-model${state?.gemini.enabled ? " is-on" : ""}`} title={state?.gemini.lastError ?? undefined}>
          {state?.gemini.enabled ? "Gemini 3.8 Flash" : "Simple rules"}
        </span>
      </header>

      <div className="tower-body">
        <ol className="tower-queue" aria-label="Agents in order">
          {queue.map((p, i) => {
            const need = p.need!;
            const t = tone(need);
            return (
              <li key={p.session}>
                <button
                  type="button"
                  className={`tower-row tone-${t}${p.session === active?.session ? " is-active" : ""}${departing.has(p.session) ? " is-departing" : ""}`}
                  aria-current={p.session === active?.session}
                  onClick={() => setSelected(p.session)}
                >
                  <span className="tower-pos">{i + 1}</span>
                  <AgentMark agent={p.agent} size={16} />
                  <span className="tower-row-main">
                    <span className="tower-row-name">{callsign(p)}</span>
                    <span className="tower-row-line">{need.reason ? `${need.reason}. ` : ""}{need.card?.summary ?? whatItWants(need)}</span>
                  </span>
                  <span className="tower-row-meta">
                    <span className={`tower-chip tone-${t}`}>{TONE_WORD[t]}</span>
                    <span className="tower-wait">{waited(need.since, now)}</span>
                  </span>
                </button>
              </li>
            );
          })}
          {inFlight.length > 0 && (
            <li className="tower-flight">
              <PlaneTakeoff size={14} aria-hidden="true" />
              <span>In flight: {inFlight.map(callsign).join(", ")}</span>
            </li>
          )}
        </ol>

        <div className="tower-strip-host">
          {active?.need ? (
            <Strip
              plane={active}
              now={now}
              editing={editing}
              draft={draft}
              editRef={editRef}
              error={error}
              onDraft={setDraft}
              onAccept={() => accept(active)}
              onEdit={() => startEdit(active)}
              onSendEdit={() => sendEdit(active)}
              onCancelEdit={() => setEditing(false)}
              onSkip={() => void answer(active, { choice: "skip" })}
              onOpen={() => active.pane && onOpenPane(active.pane)}
            />
          ) : (
            <div className="tower-clear">
              <h2>All clear</h2>
              <p>{offline ? "Start the Plane Sight server with npm start in the planesight folder." : inFlight.length ? "Your agents are working. Nothing needs you right now." : "No agent needs you."}</p>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

interface StripProps {
  plane: Plane;
  now: number;
  editing: boolean;
  draft: string;
  editRef: React.RefObject<HTMLTextAreaElement>;
  error: string | null;
  onDraft: (text: string) => void;
  onAccept: () => void;
  onEdit: () => void;
  onSendEdit: () => void;
  onCancelEdit: () => void;
  onSkip: () => void;
  onOpen: () => void;
}

function Strip({ plane, now, editing, draft, editRef, error, onDraft, onAccept, onEdit, onSendEdit, onCancelEdit, onSkip, onOpen }: StripProps) {
  const need = plane.need!;
  const card = need.card;
  const action = card?.proposal.action ?? "allow";
  const meta = ACTIONS[action];
  const editAction = EDIT_ACTION[action] ?? action;
  const t = tone(need);

  return (
    <article className={`tower-strip tone-${t}`} aria-label={`Next: ${callsign(plane)}`}>
      <header className="tower-strip-head">
        <AgentMark agent={plane.agent} size={22} />
        <div>
          <h2>{callsign(plane)}</h2>
          <p className="tower-strip-sub">{[plane.repo, plane.agent].filter(Boolean).join(", ")}. Waiting {waited(need.since, now)}.</p>
        </div>
        <span className={`tower-chip tone-${t}`}>{TONE_WORD[t]}</span>
      </header>

      <p className="tower-wants">{whatItWants(need)}</p>
      <p className="tower-summary">{card?.summary ?? need.message ?? (need.cardPending ? "The tower is reading this agent." : "")}</p>

      {need.collision && (
        <p className="tower-collision" role="alert">
          <TriangleAlert size={16} aria-hidden="true" />
          {need.collision.other} already edited {need.collision.file}. Approving this overwrites its work.
        </p>
      )}

      <div className="tower-proposal">
        {!card ? (
          <p className="tower-why">{need.cardPending ? "Gemini is writing a proposal." : "No proposal yet."}</p>
        ) : editing ? (
          <>
            <label className="tower-proposal-head" htmlFor="tower-edit">
              {editAction === "deny" ? "Your reason for denying" : editAction === "prompt" ? "Your next prompt" : "Your answer"}
            </label>
            <textarea id="tower-edit" ref={editRef} className="input tower-edit" value={draft} onChange={(e) => onDraft(e.target.value)} rows={4} />
          </>
        ) : (
          <>
            <p className="tower-proposal-head">{meta.heading}</p>
            {card.proposal.text && <p className="tower-proposal-text">{card.proposal.text}</p>}
            <p className="tower-why">{card.reasoning}</p>
          </>
        )}
      </div>

      {error && <p className="tower-error" role="alert">{error}</p>}

      <div className="tower-actions">
        {editing ? (
          <>
            <button type="button" className="btn btn-primary" onClick={onSendEdit}>Send <span className="kbd">⌘⏎</span></button>
            <button type="button" className="btn" onClick={onCancelEdit}>Cancel <span className="kbd">Esc</span></button>
          </>
        ) : (
          <>
            <button type="button" className="btn btn-primary" disabled={!card} onClick={onAccept}>{meta.button} <span className="kbd">⏎</span></button>
            <button type="button" className="btn" disabled={!card} onClick={onEdit}>Edit <span className="kbd">E</span></button>
            <button type="button" className="btn" onClick={onSkip}>Skip <span className="kbd">S</span></button>
          </>
        )}
        <button type="button" className="btn btn-ghost tower-open" disabled={!plane.pane} onClick={onOpen}>
          <SquareTerminal size={16} aria-hidden="true" /> Open terminal
        </button>
      </div>
    </article>
  );
}

.tower {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  color: var(--text);
  overflow: hidden;
}

.tower-head {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  padding: var(--space-4) var(--space-6);
  border-bottom: 1px solid var(--border);
}
.tower-title { display: flex; align-items: center; gap: var(--space-2); color: var(--text-strong); }
.tower-title h1 { margin: 0; font-size: var(--fs-xl); font-weight: 600; }
.tower-counts { margin: 0; color: var(--text-dim); font-size: var(--fs-md); }
.tower-model {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--fs-sm);
  color: var(--text-dim);
}
.tower-model::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: var(--radius-pill);
  background: var(--status-idle);
}
.tower-model.is-on::before { background: var(--status-done); }

.tower-body {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(280px, 2fr) 3fr;
}

/* ---------------------------------------------------------------- queue */

.tower-queue {
  list-style: none;
  margin: 0;
  padding: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  overflow-y: auto;
  border-right: 1px solid var(--border);
}

.tower-row {
  width: 100%;
  display: grid;
  grid-template-columns: 20px 18px 1fr auto;
  align-items: start;
  gap: var(--space-3);
  padding: var(--space-3);
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: opacity 240ms ease, transform 240ms ease;
}
.tower-row:hover { background: var(--bg-hover); }
.tower-row.is-active { background: var(--bg-elevated); border-color: var(--border-strong); }
.tower-row.is-departing { opacity: 0.3; transform: translateX(12px); }
.tower-row:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.tower-pos { color: var(--text-dim); font-size: var(--fs-sm); font-variant-numeric: tabular-nums; padding-top: 1px; }
.tower-row-main { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.tower-row-name { color: var(--text-strong); font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tower-row-line {
  color: var(--text-dim);
  font-size: var(--fs-sm);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.tower-row-meta { display: flex; flex-direction: column; align-items: flex-end; gap: var(--space-1); }
.tower-wait { color: var(--text-dim); font-size: var(--fs-xs); font-variant-numeric: tabular-nums; white-space: nowrap; }

.tower-chip {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 var(--space-2);
  border-radius: var(--radius-sm);
  font-size: var(--fs-2xs);
  font-weight: 600;
  letter-spacing: 0.04em;
  white-space: nowrap;
}
.tower-chip.tone-input { background: var(--status-blocked-tint); color: var(--status-blocked); }
.tower-chip.tone-question { background: var(--status-working-tint); color: var(--status-working); }
.tower-chip.tone-review { background: var(--status-done-tint); color: var(--status-done); }
.tower-chip.tone-danger { background: var(--danger-tint); color: var(--danger-text); }

.tower-flight {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-top: var(--space-3);
  padding: var(--space-3);
  color: var(--text-dim);
  font-size: var(--fs-sm);
}

/* ---------------------------------------------------------------- strip */

.tower-strip-host { overflow-y: auto; padding: var(--space-6); }

.tower-strip {
  max-width: 720px;
  padding: var(--space-6);
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
}

.tower-strip-head { display: flex; align-items: flex-start; gap: var(--space-3); margin-bottom: var(--space-4); }
.tower-strip-head > div { flex: 1; min-width: 0; }
.tower-strip-head h2 { margin: 0; font-size: var(--fs-display); font-weight: 600; color: var(--text-strong); line-height: 1.2; }
.tower-strip-sub { margin: var(--space-1) 0 0; color: var(--text-dim); font-size: var(--fs-sm); }

.tower-wants { margin: 0 0 var(--space-2); color: var(--text-dim); font-size: var(--fs-md); }
.tower-summary { margin: 0 0 var(--space-4); font-size: var(--fs-lg); line-height: 1.55; color: var(--text-strong); max-width: 64ch; }

.tower-collision {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  margin: 0 0 var(--space-4);
  padding: var(--space-3);
  border-radius: var(--radius-md);
  background: var(--danger-tint);
  color: var(--danger-text);
  font-size: var(--fs-md);
}
.tower-collision svg { flex: none; margin-top: 2px; }

.tower-proposal {
  padding: var(--space-4);
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
}
.tower-proposal-head { display: block; margin: 0 0 var(--space-2); font-size: var(--fs-sm); font-weight: 600; color: var(--text-dim); }
.tower-proposal-text { margin: 0 0 var(--space-2); white-space: pre-wrap; font-size: var(--fs-chat); color: var(--text-strong); line-height: 1.5; }
.tower-why { margin: 0; font-size: var(--fs-sm); color: var(--text-dim); }
.tower-edit { width: 100%; min-height: 96px; resize: vertical; font: inherit; font-size: var(--fs-chat); }

.tower-error { margin: var(--space-3) 0 0; color: var(--danger-text); font-size: var(--fs-sm); }

.tower-actions { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-top: var(--space-5); }
.tower-actions .kbd { margin-left: var(--space-1); }
.tower-open { margin-left: auto; }

.tower-clear { max-width: 520px; padding: var(--space-8) var(--space-6); color: var(--text-dim); }
.tower-clear h2 { margin: 0 0 var(--space-2); font-size: var(--fs-display); color: var(--text-strong); font-weight: 600; }
.tower-clear p { margin: 0; }

@media (max-width: 900px) {
