:root {
  --grass: #6c9c57;
  --ink: #23272d;
  --ink-soft: #5d636c;
  --paper: #fbfaf6;
  --line: #2b2f36;
  --approve: #d9534a;
  --decide: #3f7fd0;
  --review: #4f9a3f;
  --alert: #e0a020;
  --parked: #9aa1aa;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; }
body { background: var(--grass); color: var(--ink); font: 18px/1.45 "Atkinson Hyperlegible", system-ui, sans-serif; }

.viewport { position: fixed; inset: 0; display: grid; place-items: center; }

/* the stage is the image's own pixel grid; app.js scales it to the window */
.stage {
  position: relative;
  width: 1672px;
  height: 941px;
  flex: none;
  background: url("airport.png") center / 100% 100% no-repeat;
  image-rendering: pixelated;
  transform-origin: center center;
}

.brand, .tower-label, .flight-label {
  position: absolute;
  margin: 0;
  font-family: "Pixelify Sans", monospace;
  color: #fff;
  text-shadow: 2px 2px 0 var(--line);
}
.brand { left: 28px; bottom: 22px; font-size: 34px; font-weight: 600; }
.tower-label { left: 1335px; top: 262px; width: 200px; text-align: center; font-size: 18px; }
.flight-label { right: 32px; bottom: 26px; font-size: 22px; }

/* ---------------------------------------------------------------- planes */

.plane {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transition: transform 800ms cubic-bezier(.45, 0, .25, 1), opacity 500ms;
  cursor: pointer;
}
.plane-body { position: absolute; transform-origin: center; transition: transform 800ms cubic-bezier(.45, 0, .25, 1); }
.plane svg { position: absolute; display: block; shape-rendering: crispEdges; }
.plane .shadow { opacity: .28; }
.plane.is-flying { cursor: default; opacity: .85; }
.plane.is-parked { opacity: .95; }

/* the next plane breathes, nothing else moves */
.plane.is-first .plane-body svg:not(.shadow) { animation: breathe 1.6s steps(4) infinite alternate; }
@keyframes breathe { to { filter: brightness(1.18); } }

.tag {
  position: absolute;
  left: 0;
  top: -66px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px 3px;
  background: var(--tone, var(--parked));
  color: #fff;
  border: 3px solid var(--line);
  font: 600 17px/1.1 "Pixelify Sans", monospace;
  white-space: nowrap;
  pointer-events: none;
}
.tag b { font-weight: 600; opacity: .8; }
.is-parked .tag { top: 34px; background: var(--paper); color: var(--ink); font-size: 14px; border-width: 2px; }
.is-flying .tag { display: none; }

.tone-approve { --tone: var(--approve); }
.tone-decide { --tone: var(--decide); }
.tone-review { --tone: var(--review); }
.tone-alert { --tone: var(--alert); }

.plane.is-selected .tag { outline: 3px solid #fff; outline-offset: 0; }

/* ---------------------------------------------------------------- bubble */

.bubble {
  position: absolute;
  width: 440px;
  padding: 16px 18px 14px;
  background: var(--paper);
  border: 4px solid var(--line);
  box-shadow: 6px 6px 0 rgba(0, 0, 0, .28);
  transition: left 800ms cubic-bezier(.45, 0, .25, 1), top 800ms cubic-bezier(.45, 0, .25, 1);
}
.bubble::after {
  content: "";
  position: absolute;
  left: var(--tail-x, 50%);
  bottom: -16px;
  width: 20px;
  height: 20px;
  background: var(--paper);
  border-right: 4px solid var(--line);
  border-bottom: 4px solid var(--line);
  transform: translateX(-50%) rotate(45deg);
}
.bubble-head { display: flex; align-items: baseline; gap: 10px; margin-bottom: 6px; }
.bubble-head strong { font: 600 24px/1 "Pixelify Sans", monospace; }
.bubble-head .kind { color: var(--tone); font: 600 15px/1 "Pixelify Sans", monospace; }
.bubble-head .wait { margin-left: auto; color: var(--ink-soft); font-size: 15px; }
.bubble p { margin: 0 0 10px; }
.bubble .summary { font-size: 18px; }
.bubble .collision { padding: 6px 10px; background: #fbe6b8; border-left: 4px solid var(--alert); font-size: 16px; }
.bubble .proposal { padding: 8px 10px; background: #eef0e8; font-size: 16px; }
.bubble .proposal b { display: block; font-size: 14px; color: var(--ink-soft); margin-bottom: 2px; }
.bubble textarea {
  width: 100%;
  min-height: 80px;
  margin: 0 0 10px;
  padding: 8px 10px;
  font: inherit;
  font-size: 16px;
  border: 3px solid var(--line);
  background: #fff;
  resize: vertical;
}

.actions { display: flex; gap: 8px; flex-wrap: wrap; }
button {
  font: 600 17px/1 "Pixelify Sans", monospace;
  padding: 9px 12px 10px;
  border: 3px solid var(--line);
  background: #fff;
  color: var(--ink);
  cursor: pointer;
  box-shadow: 3px 3px 0 var(--line);
}
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--line); }
button.primary { background: var(--tone, var(--ink)); color: #fff; }
button:focus-visible { outline: 3px solid #fff; outline-offset: 2px; }
button kbd { font: inherit; opacity: .65; margin-left: 6px; }

@media (prefers-reduced-motion: reduce) {
  .plane, .plane-body, .bubble { transition: none; }
  .plane.is-first .plane-body svg { animation: none; }
}

