// Minimal client for the Herdr socket API: one newline-delimited JSON request per connection.
import net from "node:net";
import { execFile } from "node:child_process";
import os from "node:os";
import path from "node:path";

input.content:
// Plane Sight: an interactive airport over the agents in Herdr.
// Taxiway = agents that need you, in the tower's order. Gates and stands = idle agents.
// The grass below = agents in flight (working). Click a plane to answer, prompt, stop or inspect it.

const W = 1672;
const H = 941;
const $ = (id) => document.getElementById(id);
const stage = $("stage");

let state = { planes: [], gemini: {} };
let selected = null; // session id, or "new" for the new-flight form
let editing = false;
let outputOpen = false;
let shownAt = 0;
let lastKey = null;
const departing = new Set();
const els = new Map(); // session -> plane element

// ---------------------------------------------------------------- stage scale

function fit() {
  const s = Math.min(window.innerWidth / W, window.innerHeight / H);
  stage.style.transform = `scale(${s})`;
}
window.addEventListener("resize", fit);
fit();

// ---------------------------------------------------------------- sprites

// 18 x 12 pixels, nose to the right. o body, # outline, w windows, t tail colour.
const PLANE = [
  "........##........",
  "........#o#.......",
  "........#oo#......",
  "##......#ooo#.....",
  "#t######ooooo####.",
  "#tt#oooooooooow##.",
  "#tt#ooooooooooooo#",
  "#t######ooooo####.",
  "##......#ooo#.....",
  "........#oo#......",
  "........#o#.......",
  "........##........",
];
const PX = 4;
const TONES = { approve: "#d9534a", decide: "#3f7fd0", review: "#4f9a3f", alert: "#e0a020", parked: "#9aa1aa", flying: "#ffffff" };

function planeSvg(tail, shadow = false) {
  const colors = shadow ? { o: "#000", "#": "#000", w: "#000", t: "#000" } : { o: "#eef0f3", "#": "#2b2f36", w: "#4f8fd8", t: tail };
  let rects = "";
  PLANE.forEach((row, y) => [...row].forEach((ch, x) => {
    if (ch !== ".") rects += `<rect x="${x * PX}" y="${y * PX}" width="${PX}" height="${PX}" fill="${colors[ch]}"/>`;
  }));
  const w = PLANE[0].length * PX;
  const h = PLANE.length * PX;
  return `<svg class="${shadow ? "shadow" : ""}" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" style="left:${-w / 2}px;top:${-h / 2}px">${rects}</svg>`;
}

// ---------------------------------------------------------------- model

function tone(p) {
  const n = p.need;
  if (!n || n.skipped) return p.status === "working" ? "flying" : "parked";
  const c = n.card?.category;
  if (n.collision || c === "collision" || c === "error") return "alert";
  if (n.kind === "landed" || c === "review") return "review";
  if (n.kind === "question" || c === "design_decision" || c === "clarification") return "decide";
  return "approve";
}
const KIND_WORD = { approve: "Needs approval", decide: "Needs a decision", review: "Ready for review", alert: "Collision", parked: "At the gate", flying: "In flight" };
const name = (p) => p.name ?? p.need?.card?.title ?? p.title?.split(" ").slice(0, 3).join(" ") ?? p.session.slice(0, 6);
const short = (s, n) => (s && s.length > n ? s.slice(0, n - 1) + "…" : s ?? "");

function waited(since) {
  if (!since) return "";
  const s = Math.max(0, Math.round((Date.now() - since) / 1000));
  if (s < 60) return `${s} s`;
  if (s < 3600) return `${Math.floor(s / 60)} min`;
  return `${Math.floor(s / 3600)} h`;
}

function groups() {
  const queue = state.planes
    .filter((p) => p.need && !p.need.skipped && !departing.has(p.session))
    .sort((a, b) => (a.need.rank ?? 999) - (b.need.rank ?? 999) || (a.need.since ?? 0) - (b.need.since ?? 0));
  const flying = state.planes.filter((p) => p.status === "working" && !queue.includes(p));
  const parked = state.planes.filter((p) => !queue.includes(p) && !flying.includes(p));
  return { queue, flying, parked };
}

// Where each plane stands on the picture, in image pixels. Angle 0 faces right.
const HOLD = { x: 1375, y: 568, a: -90 };
const RUNWAY_Y = 448;
const GATES = [{ x: 208, y: 372, a: 90 }, { x: 402, y: 372, a: 90 }];
const STANDS = [];
for (const y of [300, 205]) for (let x = 620; x <= 1240; x += 100) STANDS.push({ x, y, a: 0 });

function layout({ queue, flying, parked }) {
  const spots = new Map();
  queue.forEach((p, i) => {
    const spot = i === 0 ? HOLD : { x: 1290 - (i - 1) * 96, y: 633, a: 0 };
    if (spot.x > 40) spots.set(p.session, { ...spot, s: 1, kind: "queue", rank: i });
  });
  [...GATES, ...STANDS].slice(0, parked.length).forEach((spot, i) => spots.set(parked[i].session, { ...spot, s: 0.85, kind: "parked" }));
  const cols = Math.min(Math.max(flying.length, 1), 8);
  flying.forEach((p, i) => {
    const x = 160 + (i % cols) * (1350 / Math.max(cols - 1, 1));
    const y = 760 + Math.floor(i / cols) * 95 + (i % 2) * 28;
    spots.set(p.session, { x, y, a: -12, s: 0.75, kind: "flying" });
  });
  return spots;
}

// ---------------------------------------------------------------- render

function render() {
  const g = groups();
  const spots = layout(g);

  if (selected !== "new" && !state.planes.some((p) => p.session === selected)) selected = null;
  if (!selected && g.queue[0]) selected = g.queue[0].session;
  const sel = state.planes.find((p) => p.session === selected);
  const key = sel ? `${sel.session}:${sel.need?.key ?? sel.status}` : selected;
  if (key !== lastKey) { lastKey = key; shownAt = Date.now(); editing = false; }

  for (const p of state.planes) {
    const spot = spots.get(p.session);
    if (!spot || departing.has(p.session)) continue;
    let el = els.get(p.session);
    const t = tone(p);
    if (!el) {
      el = document.createElement("div");
      el.className = "plane";
      el.innerHTML = `<div class="plane-body"></div><div class="tag"></div>`;
      el.addEventListener("click", (e) => { e.stopPropagation(); select(p.session); });
      // a new plane rolls out of the terminal, or appears where it already is
      el.style.transform = spot.kind === "queue" ? "translate(500px, 372px)" : `translate(${spot.x}px, ${spot.y}px)`;
      el.style.opacity = "0";
      $("planes").append(el);
      els.set(p.session, el);
      requestAnimationFrame(() => { el.style.opacity = ""; place(el, spot); });
    } else {
      place(el, spot);
    }
    if (el.dataset.tone !== t) {
      el.dataset.tone = t;
      el.querySelector(".plane-body").innerHTML = planeSvg(TONES[t], true) + planeSvg(TONES[t]);
      el.querySelector(".plane-body .shadow").style.transform = `translate(${spot.kind === "flying" ? 26 : 5}px, ${spot.kind === "flying" ? 26 : 5}px)`;
    }
    el.className = `plane tone-${t} is-${spot.kind}${spot.rank === 0 ? " is-first" : ""}${p.session === selected ? " is-selected" : ""}`;
    el.querySelector(".tag").innerHTML = spot.kind === "queue" ? `<b>${spot.rank + 1}</b>${short(name(p), 16)}` : short(name(p), 12);
  }
  for (const [session, el] of els) {
    if (spots.has(session) || departing.has(session)) continue;
    el.style.opacity = "0";
    setTimeout(() => el.remove(), 500);
    els.delete(session);
  }

  $("tower").textContent = state.gemini.enabled ? "Gemini 3.8 Flash" : "Tower: simple rules";
  $("flight").textContent = g.flying.length ? `${g.flying.length} in flight` : "";
  renderBubble(spots);
}

function place(el, spot) {
  el.style.transform = `translate(${spot.x}px, ${spot.y}px)`;
  el.querySelector(".plane-body").style.transform = `rotate(${spot.a}deg) scale(${spot.s})`;
  el.dataset.x = spot.x;
  el.dataset.y = spot.y;
}

// ---------------------------------------------------------------- bubble

function h(tag, attrs = {}, ...children) {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k.startsWith("on")) e.addEventListener(k.slice(2), v);
    else if (v !== null && v !== undefined && v !== false) e.setAttribute(k, v);
  }
  e.append(...children.flat().filter((c) => c !== null && c !== undefined && c !== false));
  return e;
}

const ACTIONS = {
  allow: { label: "Approve", head: "Proposed: approve" },
  deny: { label: "Deny", head: "Proposed: deny and tell it why" },
  answer: { label: "Answer", head: "Proposed answer" },
  prompt: { label: "Send", head: "Proposed next prompt" },
  dismiss: { label: "Park it", head: "Nothing more to do" },
};
const EDIT_ACTION = { allow: "deny", dismiss: "prompt" };

function renderBubble(spots) {
  const host = $("bubble");
  // keep a half-typed answer or prompt; the next update redraws the bubble after it is sent
  if (host.contains(document.activeElement) && document.activeElement.tagName === "TEXTAREA") return;
  if (!selected) { host.replaceChildren(); return; }

  let anchor;
  let body;
  if (selected === "new") {
    anchor = { x: 310, y: 120 };
    body = newFlightForm();
  } else {
    const p = state.planes.find((x) => x.session === selected);
    const spot = spots.get(selected);
    if (!p || !spot) { host.replaceChildren(); return; }
    anchor = { x: spot.x, y: spot.y - (spot.kind === "queue" ? 80 : 44) };
    body = p.need && !p.need.skipped ? decision(p) : flightCard(p);
  }

  const bubble = h("section", { class: `bubble tone-${selected === "new" ? "review" : tone(state.planes.find((x) => x.session === selected))}`, onclick: (e) => e.stopPropagation() }, body);
  host.replaceChildren(bubble);
  // above the anchor, kept inside the picture
  const bw = 440;
  const left = Math.min(Math.max(anchor.x - bw / 2, 12), W - bw - 12);
  const height = bubble.offsetHeight;
  const below = anchor.y - height - 24 < 8;
  bubble.style.left = `${left}px`;
  bubble.style.top = `${below ? anchor.y + 110 : anchor.y - height - 24}px`;
  bubble.style.setProperty("--tail-x", `${Math.min(Math.max(anchor.x - left, 24), bw - 24)}px`);
  if (below) bubble.classList.add("is-below");
}

function head(p) {
  return h("div", { class: "bubble-head" },
    h("strong", {}, short(name(p), 22)),
    h("span", { class: "kind" }, KIND_WORD[tone(p)]),
    h("span", { class: "wait" }, p.need ? waited(p.need.since) : ""));
}

function decision(p) {
  const n = p.need;
  const card = n.card;
  const action = card?.proposal?.action ?? "allow";
  const editAction = EDIT_ACTION[action] ?? action;
  return [
    head(p),
    h("p", { class: "summary" }, card?.summary ?? n.message ?? (n.cardPending ? "The tower is reading this agent." : wants(n))),
    n.collision && h("p", { class: "collision" }, `${n.collision.other} already edited ${n.collision.file}.`),
    editing
      ? h("textarea", { id: "edit", "aria-label": editAction === "prompt" ? "Your next prompt" : "Your answer" }, card?.proposal?.text ?? "")
      : card && h("p", { class: "proposal" }, h("b", {}, ACTIONS[action].head), card.proposal.text || card.reasoning),
    h("div", { class: "actions" },
      editing
        ? [h("button", { class: "primary", onclick: () => sendEdit(p, editAction) }, "Send", h("kbd", {}, "⌘⏎")),
           h("button", { onclick: () => { editing = false; render(); } }, "Cancel")]
        : [h("button", { class: "primary", disabled: card ? null : "", onclick: () => accept(p) }, ACTIONS[action].label, h("kbd", {}, "⏎")),
           h("button", { disabled: card ? null : "", onclick: () => startEdit() }, "Edit", h("kbd", {}, "E")),
           h("button", { onclick: () => post(`/api/answer/${p.session}`, { choice: "skip", key: n.key }) }, "Skip", h("kbd", {}, "S"))],
      h("button", { onclick: () => toggleOutput(p) }, outputOpen ? "Hide output" : "Output"),
      h("button", { onclick: () => post(`/api/focus/${p.session}`) }, "Herdr")),
    outputOpen && output(p),
  ];
}

function wants(n) {
  if (n.kind === "approval") return `Asks to run ${n.request?.tool ?? "a tool"}.`;
  if (n.kind === "question") return "Asks you a question.";
  if (n.kind === "landed") return "Finished its turn.";
  return "Waits at a prompt in its terminal.";
}

function flightCard(p) {
  const working = p.status === "working";
  return [
    head(p),
    h("p", { class: "summary" }, working ? `Working in ${p.repo ?? "its worktree"}.` : `Idle in ${p.repo ?? "its worktree"}.`),
    h("textarea", { id: "prompt", placeholder: working ? "Queue a message for this agent" : "What should it do next?", "aria-label": "Prompt" }),
    h("div", { class: "actions" },
      h("button", { class: "primary", onclick: () => sendPrompt(p) }, "Send", h("kbd", {}, "⌘⏎")),
      working && h("button", { onclick: () => post(`/api/stop/${p.session}`) }, "Stop"),
      h("button", { onclick: () => toggleOutput(p) }, outputOpen ? "Hide output" : "Output"),
      h("button", { onclick: () => post(`/api/focus/${p.session}`) }, "Herdr")),
    outputOpen && output(p),
  ];
}

function newFlightForm() {
  let repo = "";
  try { repo = localStorage.getItem("planesight:repo") ?? ""; } catch {}
  return [
    h("div", { class: "bubble-head" }, h("strong", {}, "New flight"), h("span", { class: "kind" }, "Starts an agent in its own worktree")),
    h("input", { id: "repo", class: "field", placeholder: "/path/to/repo", value: repo, "aria-label": "Repository" }),
    h("select", { id: "kind", class: "field", "aria-label": "Agent" }, h("option", { value: "claude" }, "Claude Code"), h("option", { value: "codex" }, "Codex")),
    h("textarea", { id: "prompt", placeholder: "What should the agent do?", "aria-label": "Task" }),
    h("div", { class: "actions" },
      h("button", { class: "primary", onclick: launch }, "Take off", h("kbd", {}, "⌘⏎")),
      h("button", { onclick: () => { selected = null; render(); } }, "Cancel")),
  ];
}

function output(p) {
  const pre = h("pre", { class: "output" }, "…");
  fetch(`/api/tail/${p.session}`).then((r) => r.text()).then((t) => { pre.textContent = t.trimEnd() || "(empty)"; pre.scrollTop = pre.scrollHeight; });
  return pre;
}

// ---------------------------------------------------------------- actions

async function post(url, body) {
  const res = await fetch(url, { method: "POST", body: body ? JSON.stringify(body) : undefined }).catch(() => null);
  if (!res?.ok) console.warn(url, res && (await res.text()));
  return res;
}

function select(session) {
  selected = session;
  outputOpen = false;
  editing = false;
  render();
}

function toggleOutput() {
  outputOpen = !outputOpen;
  render();
}

function startEdit() {
  editing = true;
  render();
  const t = $("edit");
  t?.focus();
  t?.setSelectionRange(t.value.length, t.value.length);
}

async function accept(p) {
  const card = p.need?.card;
  if (!card) return;
  if (card.proposal.action !== "dismiss") takeoff(p.session);
  selected = null;
  await post(`/api/answer/${p.session}`, { choice: "accept", key: p.need.key });
}

async function sendEdit(p, action) {
  const text = $("edit")?.value.trim() ?? "";
  editing = false;
  takeoff(p.session);
  selected = null;
  await post(`/api/answer/${p.session}`, { choice: "edit", action, text, key: p.need.key });
}

async function sendPrompt(p) {
  const text = $("prompt")?.value.trim();
  if (!text) return;
  $("prompt").blur();
  if (p.status !== "working") takeoff(p.session);
  selected = null;
  await post(`/api/prompt/${p.session}`, { text });
}

async function launch() {
  const repo = $("repo").value.trim();
  const prompt = $("prompt").value.trim();
  if (!repo || !prompt) return;
  try { localStorage.setItem("planesight:repo", repo); } catch {}
  $("prompt").blur();
  selected = null;
  render();
  await post("/api/launch", { repo, prompt, kind: $("kind").value });
}

// The one orchestrated moment: up the connector, along the runway, and off the edge of the picture.
function takeoff(session) {
  const el = els.get(session);
  if (!el) return;
  departing.add(session);
  els.delete(session);
  const body = el.querySelector(".plane-body");
  const x = Number(el.dataset.x);
  const y = Number(el.dataset.y);
  el.style.transition = "none";
  body.style.transition = "none";
  el.classList.remove("is-first", "is-selected");
  el.querySelector(".tag").style.display = "none";
  const path = [
    { transform: `translate(${x}px, ${y}px)` },
    { transform: `translate(${HOLD.x}px, ${HOLD.y}px)`, offset: 0.25 },
    { transform: `translate(${HOLD.x}px, ${RUNWAY_Y}px)`, offset: 0.4 },
    { transform: `translate(1600px, ${RUNWAY_Y}px)`, offset: 0.8, easing: "ease-in" },
    { transform: `translate(1760px, ${RUNWAY_Y - 60}px)` },
  ];
  el.animate(path, { duration: 2600, easing: "ease-in-out", fill: "forwards" });
  body.animate([
    { transform: body.style.transform },
    { transform: "rotate(-90deg) scale(1)", offset: 0.25 },
    { transform: "rotate(-90deg) scale(1)", offset: 0.4 },
    { transform: "rotate(0deg) scale(1)", offset: 0.48 },
    { transform: "rotate(0deg) scale(1.05)", offset: 0.8 },
    { transform: "rotate(-8deg) scale(1.4)" },
  ], { duration: 2600, easing: "ease-in-out", fill: "forwards" });
  el.querySelector(".shadow")?.animate([{ transform: "translate(5px, 5px)" }, { transform: "translate(5px, 5px)", offset: 0.8 }, { transform: "translate(40px, 50px)" }], { duration: 2600, fill: "forwards" });
  setTimeout(() => { el.remove(); departing.delete(session); render(); }, 2700);
}

// ---------------------------------------------------------------- input

stage.addEventListener("click", (e) => {
  // the terminal building opens the new-flight form; empty ground closes the bubble
  const r = stage.getBoundingClientRect();
  const x = ((e.clientX - r.left) / r.width) * W;
  const y = ((e.clientY - r.top) / r.height) * H;
  if (x > 125 && x < 500 && y > 95 && y < 255) select("new");
  else if (!e.target.closest(".bubble")) { selected = null; render(); }
});

document.addEventListener("keydown", (e) => {
  const inField = e.target.closest?.("input, textarea, select");
  const p = state.planes.find((x) => x.session === selected);
  if (e.key === "Escape") { editing = false; selected = null; e.target.blur?.(); render(); return; }
  if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
    e.preventDefault();
    if (selected === "new") launch();
    else if (editing && p) sendEdit(p, EDIT_ACTION[p.need.card?.proposal?.action] ?? p.need.card?.proposal?.action);
    else if (p && $("prompt")) sendPrompt(p);
    return;
  }
  if (inField || e.target.closest?.("button")) return;
  const { queue } = groups();
  if (e.key === "Enter" && p?.need && !p.need.skipped) {
    e.preventDefault();
    // a bubble that just opened is read before it is answered
    if (!e.repeat && Date.now() - shownAt > 700) accept(p);
  } else if ((e.key === "e" || e.key === "E") && p?.need) { e.preventDefault(); startEdit(); }
  else if ((e.key === "s" || e.key === "S") && p?.need) post(`/api/answer/${p.session}`, { choice: "skip", key: p.need.key });
  else if (e.key === "n" || e.key === "N") select("new");
  else if (["ArrowRight", "ArrowLeft", "ArrowUp", "ArrowDown", "Tab"].includes(e.key) && queue.length) {
    e.preventDefault();
    const i = queue.findIndex((x) => x.session === selected);
    const step = e.key === "ArrowLeft" || e.key === "ArrowDown" || (e.key === "Tab" && !e.shiftKey) ? 1 : -1;
    select(queue[(Math.max(i, 0) + step + queue.length) % queue.length].session);
  }
});

// waiting times tick without redrawing the bubble
setInterval(() => {
  const p = state.planes.find((x) => x.session === selected);
  const wait = document.querySelector(".bubble .wait");
  if (p?.need && wait) wait.textContent = waited(p.need.since);
}, 1000);

// ---------------------------------------------------------------- boot

await document.fonts.load('16px "Pixelify Sans"').catch(() => {});
const events = new EventSource("/events");
events.onmessage = (e) => {
  state = JSON.parse(e.data);
  render();
};

