// Generate the plane sprite with Nano Banana, in the style of web/airport.png.
// Run once: node --env-file=.env scripts/make-sprites.mjs. The page keys out the magenta background.
import { GoogleGenAI } from "@google/genai";
import { readFileSync, writeFileSync } from "node:fs";

const ROOT = new URL("..", import.meta.url).pathname;
const client = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
const reference = readFileSync(`${ROOT}web/airport.png`).toString("base64");

const interaction = await client.interactions.create({
  model: "gemini-nano-banana-2.1",
  input: [
    { type: "image", data: reference, mime_type: "image/png" },
    {
      type: "text",
      text: "Draw one small passenger jet seen from directly above, nose pointing to the right, in exactly the same flat pixel art style as this airport image: the same light grey and white colours, dark outline and blue windows. The plane fills most of the image and is centred. The background is one flat solid pure magenta colour (#FF00FF) with no shadow, no ground, no text and nothing else.",
    },
  ],
  response_modalities: ["image"],
  response_format: { type: "image", aspect_ratio: "1:1" },
});

const image = interaction.output_image ?? interaction.outputs?.find?.((o) => o.type === "image");
if (!image?.data) {
  console.error("No image in the response:", JSON.stringify(interaction).slice(0, 800));
  process.exit(1);
}
writeFileSync(`${ROOT}web/plane.png`, Buffer.from(image.data, "base64"));
console.log("wrote web/plane.png", image.mime_type);

