// The airport in Phaser 4: the picture, the planes, their motion and the takeoff.
// app.js owns the data and the HTML bubble; this module only draws and reports clicks.

const W = 1672;
const H = 941;
const TONES = { approve: 0xd9534a, decide: 0x3f7fd0, review: 0x4f9a3f, alert: 0xe0a020, parked: 0x9aa1aa, flying: 0xffffff };
const INK = 0x2b2f36;
const PAD = 4; // room around the 96 px sprite for its outline
const SIZE = 96 + PAD * 2;
const TAXI_Y = 633;
const HOLD_X = 1375;
const RUNWAY_Y = 448;

// From the keyed sprite canvas: the plane, a black shadow, and one outline per status colour.
function makeTextures(scene, sprite) {
  const canvas = (draw) => {
    const c = document.createElement("canvas");
    c.width = c.height = SIZE;
    draw(c.getContext("2d"));
    return c;
  };
  const silhouette = (color, spread) => canvas((ctx) => {
    for (let dx = -spread; dx <= spread; dx++) for (let dy = -spread; dy <= spread; dy++) ctx.drawImage(sprite, PAD + dx, PAD + dy);
    ctx.globalCompositeOperation = "source-in";
    ctx.fillStyle = color;
    ctx.fillRect(0, 0, SIZE, SIZE);
  });
  scene.textures.addCanvas("plane", canvas((ctx) => ctx.drawImage(sprite, PAD, PAD)));
  scene.textures.addCanvas("shadow", silhouette("#000", 0));
  for (const [tone, color] of Object.entries(TONES)) {
    scene.textures.addCanvas(`outline-${tone}`, silhouette(`#${color.toString(16).padStart(6, "0")}`, 3));
  }
  scene.textures.addCanvas("puff", (() => {
    const c = document.createElement("canvas");
    c.width = c.height = 6;
    const ctx = c.getContext("2d");
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, 6, 6);
    return c;
  })());
}

class AirportScene extends Phaser.Scene {
  constructor(opts) {
    super("airport");
    this.opts = opts;
    this.planes = new Map(); // session -> container
    this.model = null;
    this.selected = null;
  }

  preload() {
    this.load.image("airport", "airport.png");
  }

  create() {
    this.add.image(0, 0, "airport").setOrigin(0, 0).setDisplaySize(W, H);
    makeTextures(this, this.opts.sprite);
    this.bracket = this.add.graphics().setDepth(40);
    // a click that hits no plane is a click on the ground
    this.input.on("pointerdown", (pointer, over) => {
      if (!over.length) this.opts.onGround(pointer.worldX, pointer.worldY);
    });
    if (this.model) this.apply(this.model);
  }

  update(_time, delta) {
    // planes in flight circle slowly, unless you are looking at one
    for (const c of this.planes.values()) {
      if (!c.orbit || c.departing || c.session === this.selected) continue;
      const o = c.orbit;
      o.phase += (delta / 1000) * o.speed;
      c.setPosition(o.cx + o.rx * Math.cos(o.phase), o.cy + o.ry * Math.sin(o.phase));
      c.body.rotation = Math.atan2(o.ry * Math.cos(o.phase), -o.rx * Math.sin(o.phase));
    }
    this.drawBracket();
  }

  makePlane(p) {
    const shadow = this.add.image(5, 5, "shadow").setAlpha(0.28);
    const outline = this.add.image(0, 0, "outline-parked").setVisible(false);
    const art = this.add.image(0, 0, "plane");
    const body = this.add.container(0, 0, [shadow, outline, art]);
    const label = this.add.text(0, 0, "", { fontFamily: '"Pixelify Sans", monospace', fontSize: "17px", color: "#ffffff" }).setOrigin(0.5);
    const tagBox = this.add.rectangle(0, 0, 10, 10, TONES.parked).setStrokeStyle(3, INK);
    const tag = this.add.container(0, -64, [tagBox, label]);
    const c = this.add.container(0, 0, [body, tag]);
    Object.assign(c, { session: p.session, body, shadow, outline, art, tag, tagBox, label });
    c.setSize(80, 80).setInteractive({ useHandCursor: true });
    c.on("pointerdown", () => this.opts.onSelect(p.session));
    return c;
  }

  apply(model) {
    this.model = model;
    this.selected = model.selected;
    if (!this.sys.isActive() || !this.textures.exists("plane")) return;
    const seen = new Set();

    for (const p of model.planes) {
      seen.add(p.session);
      let c = this.planes.get(p.session);
      if (c?.departing) continue;
      const spot = p.spot;
      const isNew = !c;
      if (isNew) {
        c = this.makePlane(p);
        this.planes.set(p.session, c);
        // a new plane in the queue taxis in from the left; others fade in where they belong
        if (spot.kind === "queue") c.setPosition(-60, TAXI_Y);
        else c.setPosition(spot.x, spot.y).setAlpha(0);
        c.body.setAngle(spot.kind === "queue" ? 0 : spot.a).setScale(spot.s);
      }

      // look
      c.setDepth(spot.kind === "flying" ? 30 : spot.kind === "queue" ? 20 - spot.rank * 0.01 : 10);
      c.outline.setTexture(`outline-${p.tone}`).setVisible(spot.kind === "queue");
      c.shadow.setPosition(spot.kind === "flying" ? 26 : 5, spot.kind === "flying" ? 26 : 5);
      c.label.setText(p.label);
      c.label.setFontSize(spot.kind === "parked" ? 14 : 17);
      c.label.setColor(spot.kind === "parked" ? "#23272d" : "#ffffff");
      c.tagBox.setFillStyle(spot.kind === "parked" ? 0xfbfaf6 : TONES[p.tone]);
      c.tagBox.setSize(c.label.width + 18, c.label.height + 8);
      c.tagBox.setStrokeStyle(p.session === model.selected ? 4 : 3, p.session === model.selected ? 0xffffff : INK);
      c.tag.setVisible(spot.kind === "queue" || (spot.kind === "parked" && p.session === model.selected));
      this.setPulse(c, spot.kind === "queue" && spot.rank === 0);

      // motion
      if (spot.kind === "flying") {
        if (!c.orbit) {
          c.orbit = { cx: spot.x, cy: spot.y, rx: 46, ry: 16, phase: Math.random() * Math.PI * 2, speed: 0.35 + Math.random() * 0.15 };
          this.tweens.add({ targets: c, alpha: 0.9, duration: 600 });
          this.tweens.add({ targets: c.body, scale: spot.s, duration: 600 });
        } else {
          c.orbit.cx = spot.x;
          c.orbit.cy = spot.y;
        }
      } else {
        c.orbit = null;
        if (c.target?.x !== spot.x || c.target?.y !== spot.y || isNew) {
          const distance = Phaser.Math.Distance.Between(c.x, c.y, spot.x, spot.y);
          const duration = Phaser.Math.Clamp(distance * 3, 500, 1800);
          this.tweens.add({ targets: c, x: spot.x, y: spot.y, alpha: 1, duration, ease: "Sine.easeInOut" });
          const turn = Phaser.Math.Angle.ShortestBetween(c.body.angle, spot.a);
          this.tweens.add({ targets: c.body, angle: c.body.angle + turn, scale: spot.s, duration: Math.min(duration, 700), ease: "Sine.easeInOut" });
        }
      }
      c.target = spot;
    }

    for (const [session, c] of this.planes) {
      if (seen.has(session) || c.departing) continue;
      this.planes.delete(session);
      this.tweens.add({ targets: c, alpha: 0, duration: 400, onComplete: () => c.destroy() });
    }
  }

  setPulse(c, on) {
    if (on && !c.pulse) {
      c.pulse = this.tweens.add({ targets: c.outline, alpha: 0.35, duration: 900, yoyo: true, repeat: -1, ease: "Sine.easeInOut" });
    } else if (!on && c.pulse) {
      c.pulse.stop();
      c.pulse = null;
      c.outline.setAlpha(1);
    }
  }

  drawBracket() {
    this.bracket.clear();
    const c = this.selected && this.planes.get(this.selected);
    if (!c || c.departing) return;
    const r = 44 * c.body.scale;
    this.bracket.lineStyle(4, 0xffffff, 0.95);
    for (const [dx, dy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
      const x = c.x + dx * r;
      const y = c.y + dy * r;
      this.bracket.lineBetween(x, y, x - dx * 14, y);
      this.bracket.lineBetween(x, y, x, y - dy * 14);
    }
  }

  positionOf(session) {
    const c = this.planes.get(session);
    return c ? { x: c.x, y: c.y } : null;
  }

  // The one big moment: taxi to the connector, turn onto the runway, roll with exhaust, lift off.
  takeoff(session, done) {
    const c = this.planes.get(session);
    if (!c || c.departing) { done?.(); return; }
    c.departing = true;
    c.orbit = null;
    this.setPulse(c, false);
    this.tweens.killTweensOf([c, c.body]);
    c.tag.setVisible(false);
    c.outline.setVisible(false);
    c.disableInteractive();

    const path = new Phaser.Curves.Path(c.x, c.y);
    if (c.y > RUNWAY_Y + 60) {
      // from the taxiway or the hold line: along the taxiway, up the connector, right onto the runway
      if (Math.abs(c.y - TAXI_Y) < 8 && c.x < HOLD_X - 40) {
        path.lineTo(HOLD_X - 40, TAXI_Y);
        path.quadraticBezierTo(HOLD_X, TAXI_Y - 40, HOLD_X, TAXI_Y);
      }
      path.lineTo(HOLD_X, RUNWAY_Y + 40);
      path.quadraticBezierTo(HOLD_X + 40, RUNWAY_Y, HOLD_X, RUNWAY_Y);
    } else {
      // from a gate or stand above the runway: straight down onto it
      path.lineTo(c.x, RUNWAY_Y - 40);
      path.quadraticBezierTo(c.x + 40, RUNWAY_Y, c.x, RUNWAY_Y);
    }
    path.lineTo(1630, RUNWAY_Y);
    path.lineTo(1800, RUNWAY_Y - 70);

    const exhaust = this.add.particles(0, 0, "puff", {
      speed: { min: 6, max: 24 },
      lifespan: 650,
      scale: { start: 1.3, end: 0 },
      alpha: { start: 0.6, end: 0 },
      frequency: 22,
      emitting: false,
    }).setDepth(c.depth - 1);
    exhaust.startFollow(c);

    const startScale = c.body.scale;
    this.tweens.addCounter({
      from: 0,
      to: 1,
      duration: 3200,
      ease: "Quad.easeIn",
      onUpdate: (tween) => {
        const t = tween.getValue();
        const point = path.getPoint(t);
        const tangent = path.getTangent(t);
        c.setPosition(point.x, point.y);
        c.body.rotation = Math.atan2(tangent.y, tangent.x);
        if (t > 0.55 && !exhaust.emitting) exhaust.start();
        const lift = Phaser.Math.Clamp((t - 0.8) / 0.2, 0, 1);
        c.body.setScale(startScale + 0.4 * lift);
        c.shadow.setPosition(5 + 40 * lift, 5 + 50 * lift);
      },
      onComplete: () => {
        exhaust.stop();
        this.time.delayedCall(800, () => exhaust.destroy());
        this.planes.delete(session);
        c.destroy();
        done?.();
      },
    });
  }
}

export function createAirport(parent, opts) {
  const scene = new AirportScene(opts);
  const game = new Phaser.Game({
    type: Phaser.AUTO,
    parent,
    width: W,
    height: H,
    transparent: true,
    scale: { mode: Phaser.Scale.NONE },
    scene,
  });
  return {
    update: (model) => scene.apply(model),
    takeoff: (session, done) => scene.takeoff(session, done),
    positionOf: (session) => scene.positionOf(session),
    // the stage is scaled with CSS; Phaser has to re-read the canvas size for clicks to land right
    refresh: () => game.scale.refresh(),
  };
}

