// What the Plane Sight server sends over /events (see server/server.mjs, snapshot()).

export type Action = "allow" | "deny" | "answer" | "prompt" | "dismiss";

export interface Card {
  title: string;
  summary: string;
  category: string;
  proposal: { action: Action; text: string };
  reasoning: string;
  effort_seconds: number;
  risk: "low" | "medium" | "high";
}

export interface Need {
  kind: "approval" | "question" | "blocked" | "landed";
  key: string;
  skipped: boolean;
  since: number | null;
  rank: number | null;
  reason: string | null;
  request: { tool?: string; input?: Record<string, unknown>; expired: boolean } | null;
  message: string | null;
  collision: { file: string; other: string; otherSession: string } | null;
  card: Card | null;
  cardPending: boolean;
}

export interface Plane {
  session: string;
  pane: string | null;
  agent: string;
  name: string | null;
  title: string | null;
  repo: string | null;
  status: string;
  tokens: number | null;
  files: string[];
  need: Need | null;
}

export interface TowerState {
  now: number;
  gemini: { enabled: boolean; lastError: string | null };
  planes: Plane[];
}

/** Status colour of a plane: what it needs from you, or where it is. */
export type Tone = "approve" | "decide" | "review" | "alert" | "parked" | "flying";

export type Airline = "cloud-code" | "openair";

/** Where a plane stands on the picture, in the picture's own pixels. Heading 0 faces up, 90 faces right. */
export interface Spot {
  x: number;
  y: number;
  heading: number;
  scale: number;
  kind: "queue" | "parked" | "flying";
  rank?: number;
  /** For a plane in the queue: the connector it takes to the runway. */
  laneX?: number;
  tag: "above" | "below" | "none";
}

// Turns the server's agents into planes on the picture: who needs you, who is parked, who is flying.
import type { Airline, Plane, Spot, Tone, TowerState } from "./types";

export const W = 1672;
export const H = 941;
export const RUNWAY_Y = 450;
export const TAXI_Y = 635;
export const HOLD_Y = 612;

/** The three connectors from the taxiway to the runway, right to left. #1 waits at the right one. */
export const LANES = [1382, 818, 269];
const BEHIND = 165; // distance between planes queued on the taxiway

export function tone(p: Plane): Tone {
  const n = p.need;
  if (!n || n.skipped) return p.status === "working" ? "flying" : "parked";
  const c = n.card?.category;
  if (n.collision || c === "collision" || c === "error") return "alert";
  if (n.kind === "landed" || c === "review") return "review";
  if (n.kind === "question" || c === "design_decision" || c === "clarification") return "decide";
  return "approve";
}

export const STATUS_WORD: Record<Tone, string> = {
  approve: "Needs approval",
  decide: "Needs a decision",
  review: "Ready for review",
  alert: "Collision",
  parked: "At the gate",
  flying: "In flight",
};

export const airline = (p: Plane): Airline => (p.agent === "codex" ? "openair" : "cloud-code");
export const AIRLINE_NAME: Record<Airline, string> = { "cloud-code": "Cloud Code", openair: "OpenAir" };

/** A stable flight number per agent session, such as CC-104. */
export function flightId(p: Plane) {
  let hash = 0;
  for (const ch of p.session) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
  return `${airline(p) === "openair" ? "OA" : "CC"}-${100 + (hash % 900)}`;
}

export const name = (p: Plane) => p.name ?? p.need?.card?.title ?? p.title?.split(" ").slice(0, 3).join(" ") ?? p.session.slice(0, 6);
export const short = (s: string | null | undefined, n: number) => (s && s.length > n ? s.slice(0, n - 1) + "…" : s ?? "");

export function waited(since: number | null | undefined) {
  if (!since) return "";
  const s = Math.max(0, Math.round((Date.now() - since) / 1000));
  if (s < 60) return `${s} s`;
  if (s < 3600) return `${Math.floor(s / 60)} min`;
  return `${Math.floor(s / 3600)} h`;
}

export function groups(state: TowerState, departing: Set<string>) {
  const queue = state.planes
    .filter((p) => p.need && !p.need.skipped && !departing.has(p.session))
    .sort((a, b) => (a.need!.rank ?? 999) - (b.need!.rank ?? 999) || (a.need!.since ?? 0) - (b.need!.since ?? 0));
  const flying = state.planes.filter((p) => p.status === "working" && !queue.includes(p) && !departing.has(p.session));
  const parked = state.planes.filter((p) => !queue.includes(p) && !flying.includes(p) && !departing.has(p.session));
  return { queue, flying, parked };
}

// Taxiway places behind each lane, filled in rank order after the three hold lines.
const QUEUE_SLOTS: { x: number; lane: number }[] = [
  { x: LANES[0] - BEHIND, lane: LANES[0] },
  { x: LANES[1] - BEHIND, lane: LANES[1] },
  { x: LANES[2] - BEHIND, lane: LANES[2] },
  { x: LANES[0] - 2 * BEHIND, lane: LANES[0] },
  { x: LANES[1] - 2 * BEHIND, lane: LANES[1] },
];
const GATES = [{ x: 208, y: 352 }, { x: 402, y: 352 }];
const STANDS: { x: number; y: number }[] = [];
for (const y of [318, 214]) for (let x = 640; x <= 1240; x += 120) STANDS.push({ x, y });

export function layout({ queue, flying, parked }: ReturnType<typeof groups>) {
  const spots = new Map<string, Spot>();
  queue.forEach((p, i) => {
    if (i < LANES.length) {
      spots.set(p.session, { x: LANES[i], y: HOLD_Y, heading: 0, scale: 1, kind: "queue", rank: i, laneX: LANES[i], tag: "above" });
    } else {
      const slot = QUEUE_SLOTS[i - LANES.length];
      if (slot) spots.set(p.session, { x: slot.x, y: TAXI_Y, heading: 90, scale: 1, kind: "queue", rank: i, laneX: slot.lane, tag: "below" });
    }
  });
  [...GATES.map((g) => ({ ...g, heading: 0 })), ...STANDS.map((s) => ({ ...s, heading: 90 }))]
    .slice(0, parked.length)
    .forEach((spot, i) => spots.set(parked[i].session, { ...spot, scale: 0.55, kind: "parked", tag: "none" }));
  const cols = Math.min(Math.max(flying.length, 1), 7);
  flying.forEach((p, i) => {
    const x = 170 + (i % cols) * (1330 / Math.max(cols - 1, 1));
    const y = 790 + Math.floor(i / cols) * 90 + (i % 2) * 24;
    spots.set(p.session, { x, y, heading: 70, scale: 0.5, kind: "flying", tag: "none" });
  });
  const overflow = Math.max(0, queue.length - LANES.length - QUEUE_SLOTS.length);
  return { spots, overflow };
}

// The airport in Phaser: the picture, the planes, their motion and the takeoff.
// main.ts owns the data; the HTML layer (ui.ts) draws the flight tags and the bubble on top.
import Phaser from "phaser";
import airportUrl from "../../public/airport/pixel-airport.png?url";
import cloudCodeUrl from "../../public/airlines/cloud-code-plane-top-down.png?url";
import openAirUrl from "../../public/airlines/openair-plane-top-down.png?url";
import { H, RUNWAY_Y, TAXI_Y, W } from "./model";
import type { Airline, Spot, Tone } from "./types";

const SIZE = 160; // plane texture size in picture pixels at scale 1
const PAD = 6; // room for the outline
const TEX = SIZE + PAD * 2;
const TONE_COLOR: Record<Tone, string> = {
  approve: "#d9534a",
  decide: "#3f7fd0",
  review: "#3f9a4f",
  alert: "#e0a020",
  parked: "#9aa1aa",
  flying: "#ffffff",
};

export interface PlaneView {
  session: string;
  airline: Airline;
  tone: Tone;
  spot: Spot;
}

export interface AirportCallbacks {
  onSelect: (session: string) => void;
  onGround: (x: number, y: number) => void;
  /** Every frame: where each plane is now, so the HTML tags can follow it. */
  onFrame: (positions: Map<string, { x: number; y: number; visible: boolean }>) => void;
}

type PlaneObject = Phaser.GameObjects.Container & {
  session: string;
  body: Phaser.GameObjects.Container;
  shadow: Phaser.GameObjects.Image;
  outline: Phaser.GameObjects.Image;
  art: Phaser.GameObjects.Image;
  spot?: Spot;
  orbit?: { cx: number; cy: number; rx: number; ry: number; phase: number; speed: number } | null;
  pulse?: Phaser.Tweens.Tween | null;
  departing?: boolean;
};

export class AirportScene extends Phaser.Scene {
  private planes = new Map<string, PlaneObject>();
  private views: PlaneView[] = [];
  private selected: string | null = null;
  private ready = false;
  private bracket!: Phaser.GameObjects.Graphics;

  constructor(private callbacks: AirportCallbacks) {
    super("airport");
  }

  preload() {
    this.load.image("airport", airportUrl);
    this.load.image("src-cloud-code", cloudCodeUrl);
    this.load.image("src-openair", openAirUrl);
  }

  create() {
    this.add.image(0, 0, "airport").setOrigin(0, 0).setDisplaySize(W, H);
    for (const airline of ["cloud-code", "openair"] as Airline[]) this.makeTextures(airline);
    this.makePuff();
    this.bracket = this.add.graphics().setDepth(40);
    this.input.on("pointerdown", (pointer: Phaser.Input.Pointer, over: Phaser.GameObjects.GameObject[]) => {
      if (!over.length) this.callbacks.onGround(pointer.worldX, pointer.worldY);
    });
    this.ready = true;
    this.apply(this.views, this.selected);
  }

  /** The sprite shrunk to SIZE, a black shadow, and one outline per status colour. */
  private makeTextures(airline: Airline) {
    const source = this.textures.get(`src-${airline}`).getSourceImage() as HTMLImageElement;
    const canvas = () => {
      const c = document.createElement("canvas");
      c.width = c.height = TEX;
      return c;
    };
    const plane = canvas();
    const ctx = plane.getContext("2d")!;
    ctx.imageSmoothingQuality = "high";
    ctx.drawImage(source, PAD, PAD, SIZE, SIZE);
    this.textures.addCanvas(`plane-${airline}`, plane);

    const silhouette = (color: string, spread: number) => {
      const c = canvas();
      const s = c.getContext("2d")!;
      for (let dx = -spread; dx <= spread; dx += spread || 1) for (let dy = -spread; dy <= spread; dy += spread || 1) s.drawImage(plane, dx, dy);
      s.globalCompositeOperation = "source-in";
      s.fillStyle = color;
      s.fillRect(0, 0, TEX, TEX);
      return c;
    };
    if (!this.textures.exists("shadow")) this.textures.addCanvas("shadow", silhouette("#000", 0));
    for (const [tone, color] of Object.entries(TONE_COLOR)) this.textures.addCanvas(`outline-${airline}-${tone}`, silhouette(color, 4));
  }

  private makePuff() {
    const c = document.createElement("canvas");
    c.width = c.height = 8;
    const ctx = c.getContext("2d")!;
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, 8, 8);
    this.textures.addCanvas("puff", c);
  }

  update(_time: number, delta: number) {
    const positions = new Map<string, { x: number; y: number; visible: boolean }>();
    for (const plane of this.planes.values()) {
      const o = plane.orbit;
      // planes in flight circle slowly, unless you are looking at one
      if (o && !plane.departing && plane.session !== this.selected) {
        o.phase += (delta / 1000) * o.speed;
        plane.setPosition(o.cx + o.rx * Math.cos(o.phase), o.cy + o.ry * Math.sin(o.phase));
        plane.body.rotation = Math.atan2(o.ry * Math.cos(o.phase), -o.rx * Math.sin(o.phase)) + Math.PI / 2;
      }
      positions.set(plane.session, { x: plane.x, y: plane.y, visible: !plane.departing && plane.alpha > 0.5 });
    }
    this.callbacks.onFrame(positions);
    this.drawBracket();
  }

  private makePlane(view: PlaneView): PlaneObject {
    const shadow = this.add.image(6, 6, "shadow").setAlpha(0.25);
    const outline = this.add.image(0, 0, `outline-${view.airline}-${view.tone}`).setVisible(false);
    const art = this.add.image(0, 0, `plane-${view.airline}`);
    const body = this.add.container(0, 0, [shadow, outline, art]);
    const plane = this.add.container(0, 0, [body]) as PlaneObject;
    Object.assign(plane, { session: view.session, body, shadow, outline, art });
    plane.setSize(SIZE * 0.8, SIZE * 0.8).setInteractive({ useHandCursor: true });
    plane.on("pointerdown", () => this.callbacks.onSelect(view.session));
    return plane;
  }

  apply(views: PlaneView[], selected: string | null) {
    this.views = views;
    this.selected = selected;
    if (!this.ready) return;
    const seen = new Set<string>();

    for (const view of views) {
      seen.add(view.session);
      let plane = this.planes.get(view.session);
      if (plane?.departing) continue;
      const spot = view.spot;
      const isNew = !plane;
      if (!plane) {
        plane = this.makePlane(view);
        this.planes.set(view.session, plane);
        // a new plane in the queue taxis in from the left; others fade in where they belong
        if (spot.kind === "queue") plane.setPosition(-90, TAXI_Y);
        else plane.setPosition(spot.x, spot.y).setAlpha(0);
        plane.body.setAngle(spot.kind === "queue" ? 90 : spot.heading).setScale(spot.scale);
      }

      plane.setDepth(spot.kind === "flying" ? 30 : spot.kind === "queue" ? 20 - (spot.rank ?? 0) * 0.01 : 10);
      plane.art.setTexture(`plane-${view.airline}`);
      plane.outline.setTexture(`outline-${view.airline}-${view.tone}`).setVisible(spot.kind === "queue");
      const lift = spot.kind === "flying" ? 30 : 6;
      plane.shadow.setPosition(lift, lift);
      this.setPulse(plane, spot.kind === "queue" && spot.rank === 0);

      if (spot.kind === "flying") {
        if (!plane.orbit) {
          plane.orbit = { cx: spot.x, cy: spot.y, rx: 56, ry: 18, phase: Math.random() * Math.PI * 2, speed: 0.3 + Math.random() * 0.15 };
          this.tweens.add({ targets: plane, alpha: 0.92, duration: 600 });
          this.tweens.add({ targets: plane.body, scale: spot.scale, duration: 600 });
        } else {
          plane.orbit.cx = spot.x;
          plane.orbit.cy = spot.y;
        }
      } else {
        plane.orbit = null;
        if (isNew || plane.spot?.x !== spot.x || plane.spot?.y !== spot.y) this.moveTo(plane, spot);
      }
      plane.spot = spot;
    }

    for (const [session, plane] of this.planes) {
      if (seen.has(session) || plane.departing) continue;
      this.planes.delete(session);
      this.tweens.add({ targets: plane, alpha: 0, duration: 400, onComplete: () => plane.destroy() });
    }
  }

  /** Taxi along the taxiway first, then turn into the hold line, so planes never cut across grass. */
  private moveTo(plane: PlaneObject, spot: Spot) {
    this.tweens.killTweensOf([plane, plane.body]);
    const path = new Phaser.Curves.Path(plane.x, plane.y);
    const onTaxiway = Math.abs(plane.y - TAXI_Y) < 12;
    if (spot.kind === "queue" && spot.tag === "above" && onTaxiway && Math.abs(plane.x - spot.x) > 2) {
      path.lineTo(spot.x - 40, TAXI_Y);
      path.quadraticBezierTo(spot.x, TAXI_Y - 40, spot.x, TAXI_Y);
      path.lineTo(spot.x, spot.y);
    } else {
      path.lineTo(spot.x, spot.y);
    }
    const length = path.getLength();
    if (length < 1) {
      this.tweens.add({ targets: plane, alpha: 1, duration: 400 });
      this.tweens.add({ targets: plane.body, angle: spot.heading, scale: spot.scale, duration: 400 });
      return;
    }
    const startScale = plane.body.scale;
    const glide = spot.kind !== "queue"; // gates and stands: fade and slide, no path steering
    this.tweens.addCounter({
      from: 0,
      to: 1,
      duration: Phaser.Math.Clamp(length * 2.6, 500, 2600),
      ease: "Sine.easeInOut",
      onUpdate: (tween) => {
        const t = tween.getValue() ?? 0;
        const point = path.getPoint(t);
        plane.setPosition(point.x, point.y);
        plane.setAlpha(Math.max(plane.alpha, Math.min(1, t * 3)));
        plane.body.setScale(startScale + (spot.scale - startScale) * t);
        if (!glide && t < 0.97) {
          const tangent = path.getTangent(t);
          plane.body.rotation = Math.atan2(tangent.y, tangent.x) + Math.PI / 2;
        }
      },
      onComplete: () => {
        this.tweens.add({ targets: plane.body, angle: spot.heading, duration: 300 });
        plane.setAlpha(1);
      },
    });
  }

  private setPulse(plane: PlaneObject, on: boolean) {
    if (on && !plane.pulse) {
      plane.pulse = this.tweens.add({ targets: plane.outline, alpha: 0.3, duration: 900, yoyo: true, repeat: -1, ease: "Sine.easeInOut" });
    } else if (!on && plane.pulse) {
      plane.pulse.stop();
      plane.pulse = null;
      plane.outline.setAlpha(1);
    }
  }

  private drawBracket() {
    this.bracket.clear();
    const plane = this.selected ? this.planes.get(this.selected) : null;
    if (!plane || plane.departing) return;
    const r = (SIZE / 2) * plane.body.scale * 0.9;
    this.bracket.lineStyle(4, 0xffffff, 0.95);
    for (const [dx, dy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
      const x = plane.x + dx * r;
      const y = plane.y + dy * r;
      this.bracket.lineBetween(x, y, x - dx * 16, y);
      this.bracket.lineBetween(x, y, x, y - dy * 16);
    }
  }

  positionOf(session: string) {
    const plane = this.planes.get(session);
    return plane ? { x: plane.x, y: plane.y } : null;
  }

  /** The big moment: up the connector, right onto the runway, roll with exhaust, lift off the edge. */
  takeoff(session: string, done: () => void) {
    const plane = this.planes.get(session);
    if (!plane || plane.departing) return done();
    plane.departing = true;
    plane.orbit = null;
    this.setPulse(plane, false);
    this.tweens.killTweensOf([plane, plane.body]);
    plane.outline.setVisible(false);
    plane.disableInteractive();

    const laneX = plane.spot?.laneX ?? plane.x;
    const path = new Phaser.Curves.Path(plane.x, plane.y);
    if (plane.y > RUNWAY_Y + 60) {
      if (Math.abs(plane.y - TAXI_Y) < 12 && plane.x < laneX - 40) {
        path.lineTo(laneX - 40, TAXI_Y);
        path.quadraticBezierTo(laneX, TAXI_Y - 40, laneX, TAXI_Y);
      }
      path.lineTo(laneX, RUNWAY_Y + 40);
      path.quadraticBezierTo(laneX + 40, RUNWAY_Y, laneX, RUNWAY_Y);
    } else {
      // from a gate or stand above the runway
      path.lineTo(plane.x, RUNWAY_Y - 40);
      path.quadraticBezierTo(plane.x + 40, RUNWAY_Y, plane.x, RUNWAY_Y);
    }
    path.lineTo(1630, RUNWAY_Y);
    path.lineTo(1840, RUNWAY_Y - 80);

    const exhaust = this.add.particles(0, 0, "puff", {
      speed: { min: 8, max: 30 },
      lifespan: 700,
      scale: { start: 1.4, end: 0 },
      alpha: { start: 0.55, end: 0 },
      frequency: 20,
      emitting: false,
    }).setDepth(plane.depth - 1);
    exhaust.startFollow(plane);

    const startScale = plane.body.scale;
    const rollStart = path.getLength() > 0 ? 1 - (1630 - laneX + 230) / path.getLength() : 0.5;
    this.tweens.addCounter({
      from: 0,
      to: 1,
      duration: 2600 + path.getLength() * 0.9,
      ease: "Quad.easeIn",
      onUpdate: (tween) => {
        const t = tween.getValue() ?? 0;
        const point = path.getPoint(t);
        const tangent = path.getTangent(t);
        plane.setPosition(point.x, point.y);
        plane.body.rotation = Math.atan2(tangent.y, tangent.x) + Math.PI / 2;
        if (t > rollStart && !exhaust.emitting) exhaust.start();
        const lift = Phaser.Math.Clamp((t - 0.86) / 0.14, 0, 1);
        plane.body.setScale(startScale + 0.45 * lift);
        plane.shadow.setPosition(6 + 44 * lift, 6 + 54 * lift);
      },
      onComplete: () => {
        exhaust.stop();
        this.time.delayedCall(900, () => exhaust.destroy());
        this.planes.delete(session);
        plane.destroy();
        done();
      },
    });
  }
}

export function createAirport(parent: HTMLElement, callbacks: AirportCallbacks) {
  const scene = new AirportScene(callbacks);
  const game = new Phaser.Game({
    type: Phaser.AUTO,
    parent,
    width: W,
    height: H,
    transparent: true,
    scale: { mode: Phaser.Scale.NONE },
    scene,
  });
  return {
    scene,
    // the stage is scaled with CSS; Phaser re-reads the canvas size so clicks land on the right plane
    refresh: () => game.scale.refresh(),
  };
}

// The HTML layer over the airport: flight tags that follow the planes, and the bubble.
import { AIRLINE_NAME, STATUS_WORD, airline, flightId, name, short, tone, waited } from "./model";
import type { Action, Need, Plane, Spot } from "./types";

type Child = Node | string | null | undefined | false | Child[];

export function h(tag: string, attrs: Record<string, unknown> = {}, ...children: Child[]): HTMLElement {
  const e = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k.startsWith("on") && typeof v === "function") e.addEventListener(k.slice(2), v as EventListener);
    else if (v !== null && v !== undefined && v !== false) e.setAttribute(k, String(v));
  }
  const flat = (c: Child): (Node | string)[] => (Array.isArray(c) ? c.flatMap(flat) : c ? [c] : []);
  e.append(...children.flatMap(flat));
  return e;
}

// ---------------------------------------------------------------- flight tags

const tags = new Map<string, HTMLElement>();

/** One strip per plane in the queue, in the promo's flight-strip style. */
export function renderTags(host: HTMLElement, planes: Plane[], spots: Map<string, Spot>, selected: string | null) {
  const seen = new Set<string>();
  for (const p of planes) {
    const spot = spots.get(p.session);
    if (!spot || spot.tag === "none") continue;
    seen.add(p.session);
    let tag = tags.get(p.session);
    if (!tag) {
      tag = h("div", { class: "tag" });
      tags.set(p.session, tag);
      host.append(tag);
    }
    const status = p.need?.collision ? `Collides with ${p.need.collision.other}` : STATUS_WORD[tone(p)];
    tag.className = `tag ${airline(p)} tone-${tone(p)} is-${spot.tag}${spot.rank === 0 ? " is-next" : ""}${p.session === selected ? " is-selected" : ""}`;
    tag.replaceChildren(
      h("span", { class: "tag-line" }, h("b", {}, `${(spot.rank ?? 0) + 1}`), h("strong", {}, short(name(p), 14)), h("small", {}, flightId(p))),
      h("span", { class: "tag-status" }, status),
    );
  }
  for (const [session, tag] of tags) {
    if (seen.has(session)) continue;
    tag.remove();
    tags.delete(session);
  }
}

export function positionTags(positions: Map<string, { x: number; y: number; visible: boolean }>) {
  for (const [session, tag] of tags) {
    const at = positions.get(session);
    if (!at) continue;
    tag.style.transform = `translate(${at.x}px, ${at.y}px)`;
    tag.style.opacity = at.visible ? "1" : "0";
  }
}

// ---------------------------------------------------------------- bubble

export interface BubbleActions {
  accept: (p: Plane) => void;
  startEdit: () => void;
  sendEdit: (p: Plane, action: Action) => void;
  cancelEdit: () => void;
  skip: (p: Plane) => void;
  toggleOutput: () => void;
  focus: (p: Plane) => void;
  sendPrompt: (p: Plane) => void;
  stop: (p: Plane) => void;
  launch: () => void;
  close: () => void;
}

const ACTIONS: Record<Action, { label: string; head: string }> = {
  allow: { label: "Approve", head: "Proposed: approve" },
  deny: { label: "Deny", head: "Proposed: deny and tell it why" },
  answer: { label: "Answer", head: "Proposed answer" },
  prompt: { label: "Send", head: "Proposed next prompt" },
  dismiss: { label: "Park it", head: "Nothing more to do" },
};
export const EDIT_ACTION: Partial<Record<Action, Action>> = { allow: "deny", dismiss: "prompt" };

function head(p: Plane) {
  return h("div", { class: "bubble-head" },
    h("strong", {}, short(name(p), 24)),
    h("small", {}, `${AIRLINE_NAME[airline(p)]} ${flightId(p)}`),
    h("span", { class: "kind" }, STATUS_WORD[tone(p)]),
    h("span", { class: "wait" }, p.need ? waited(p.need.since) : ""));
}

function wants(n: Need) {
  if (n.kind === "approval") return `Asks to run ${n.request?.tool ?? "a tool"}.`;
  if (n.kind === "question") return "Asks you a question.";
  if (n.kind === "landed") return "Finished its turn.";
  return "Waits at a prompt in its terminal.";
}

function secondary(p: Plane, a: BubbleActions, outputOpen: boolean) {
  return h("span", { class: "secondary" },
    h("button", { class: "small", onclick: () => a.toggleOutput() }, outputOpen ? "Hide output" : "Output"),
    h("button", { class: "small", onclick: () => a.focus(p) }, "Herdr"));
}

function output(p: Plane) {
  const pre = h("pre", { class: "output" }, "…");
  fetch(`/api/tail/${p.session}`).then((r) => r.text()).then((t) => {
    pre.textContent = t.trimEnd() || "(empty)";
    pre.scrollTop = pre.scrollHeight;
  });
  return pre;
}

export function decision(p: Plane, a: BubbleActions, editing: boolean, outputOpen: boolean) {
  const n = p.need!;
  const card = n.card;
  const action = card?.proposal.action ?? "allow";
  const editAction = EDIT_ACTION[action] ?? action;
  return [
    head(p),
    h("p", { class: "summary" }, card?.summary ?? n.message ?? (n.cardPending ? "The tower is reading this agent." : wants(n))),
    n.collision && h("p", { class: "collision" }, `${n.collision.other} already edited ${n.collision.file}.`),
    editing
      ? h("textarea", { id: "edit", "aria-label": editAction === "prompt" ? "Your next prompt" : "Your answer" }, card?.proposal.text ?? "")
      : card && h("p", { class: "proposal" }, h("b", {}, ACTIONS[action].head), card.proposal.text || card.reasoning),
    h("div", { class: "actions" },
      editing
        ? [h("button", { class: "primary", onclick: () => a.sendEdit(p, editAction) }, "Send", h("kbd", {}, "⌘⏎")),
           h("button", { onclick: () => a.cancelEdit() }, "Cancel")]
        : [h("button", { class: "primary", disabled: card ? null : "", onclick: () => a.accept(p) }, ACTIONS[action].label, h("kbd", {}, "⏎")),
           h("button", { disabled: card ? null : "", onclick: () => a.startEdit() }, "Edit", h("kbd", {}, "E")),
           h("button", { onclick: () => a.skip(p) }, "Skip", h("kbd", {}, "S"))],
      secondary(p, a, outputOpen)),
    outputOpen && output(p),
  ];
}

export function flightCard(p: Plane, a: BubbleActions, outputOpen: boolean) {
  const working = p.status === "working";
  return [
    head(p),
    h("p", { class: "summary" }, working ? `Working in ${p.repo ?? "its worktree"}.` : `Idle in ${p.repo ?? "its worktree"}.`),
    h("textarea", { id: "prompt", placeholder: working ? "Queue a message for this agent" : "What should it do next?", "aria-label": "Prompt" }),
    h("div", { class: "actions" },
      h("button", { class: "primary", onclick: () => a.sendPrompt(p) }, "Send", h("kbd", {}, "⌘⏎")),
      working && h("button", { onclick: () => a.stop(p) }, "Stop"),
      secondary(p, a, outputOpen)),
    outputOpen && output(p),
  ];
}

export function newFlightForm(a: BubbleActions) {
  let repo = "";
  try { repo = localStorage.getItem("planesight:repo") ?? ""; } catch { /* storage blocked */ }
  return [
    h("div", { class: "bubble-head" }, h("strong", {}, "New flight"), h("span", { class: "kind" }, "Starts an agent in its own worktree")),
    h("input", { id: "repo", class: "field", placeholder: "/path/to/repo", value: repo, "aria-label": "Repository" }),
    h("select", { id: "kind", class: "field", "aria-label": "Airline" },
      h("option", { value: "claude" }, "Cloud Code (Claude Code)"),
      h("option", { value: "codex" }, "OpenAir (Codex)")),
    h("textarea", { id: "prompt", placeholder: "What should the agent do?", "aria-label": "Task" }),
    h("div", { class: "actions" },
      h("button", { class: "primary", onclick: () => a.launch() }, "Take off", h("kbd", {}, "⌘⏎")),
      h("button", { onclick: () => a.close() }, "Cancel")),
  ];
}

// Plane Sight: a live airport over the coding agents in Herdr.
// Taxiway = agents that need you, in the tower's order. Gates and stands = idle agents.
// The grass below = agents in flight. Click a plane to answer, prompt, stop or inspect it.
import "./style.css";
import logoUrl from "../../public/branding/plane-sight-logo.png?url";
import { createAirport, type PlaneView } from "./AirportScene";
import { H, W, airline, groups, layout, tone } from "./model";
import { EDIT_ACTION, decision, flightCard, h, newFlightForm, positionTags, renderTags, type BubbleActions } from "./ui";
import type { Action, Plane, TowerState } from "./types";

const $ = <T extends HTMLElement = HTMLElement>(id: string) => document.getElementById(id) as T;
const stage = $("stage");

let state: TowerState = { now: 0, gemini: { enabled: false, lastError: null }, planes: [] };
let selected: string | null = null; // a session, or "new" for the new-flight form
let pinned = false; // true when you picked the plane; otherwise the bubble follows #1
let editing = false;
let outputOpen = false;
let shownAt = 0;
let lastKey: string | null = null;
const departing = new Set<string>();

// ---------------------------------------------------------------- airport

const airport = createAirport($("game"), {
  onSelect: (session) => select(session),
  onGround: (x, y) => {
    // the terminal building opens the new-flight form; anything else closes the bubble
    if (x > 125 && x < 500 && y > 95 && y < 255) select("new");
    else { selected = null; pinned = true; editing = false; render(); }
  },
  onFrame: (positions) => positionTags(positions),
});

function fit() {
  const s = Math.min(window.innerWidth / W, window.innerHeight / H);
  stage.style.transform = `translate(-50%, -50%) scale(${s})`;
  airport.refresh();
}
window.addEventListener("resize", fit);
$<HTMLImageElement>("logo").src = logoUrl;

// ---------------------------------------------------------------- render

function render() {
  const g = groups(state, departing);
  const { spots, overflow } = layout(g);

  if (selected !== "new" && !state.planes.some((p) => p.session === selected)) selected = null;
  if (!pinned && selected !== "new") selected = g.queue[0]?.session ?? null;
  const sel = state.planes.find((p) => p.session === selected);
  const key = sel ? `${sel.session}:${sel.need?.key ?? sel.status}` : selected;
  if (key !== lastKey) { lastKey = key; shownAt = Date.now(); editing = false; }

  const views: PlaneView[] = state.planes
    .filter((p) => spots.has(p.session) && !departing.has(p.session))
    .map((p) => ({ session: p.session, airline: airline(p), tone: tone(p), spot: spots.get(p.session)! }));
  airport.scene.apply(views, selected === "new" ? null : selected);
  renderTags($("tags"), state.planes.filter((p) => !departing.has(p.session)), spots, selected);

  $("tower").textContent = state.gemini.enabled ? "Gemini 3.8 Flash" : "Simple rules";
  $("flight").textContent = g.flying.length ? `${g.flying.length} in flight` : "";
  $("overflow").textContent = overflow ? `+${overflow} more waiting` : "";
  renderBubble(spots);
}

function renderBubble(spots: ReturnType<typeof layout>["spots"]) {
  const host = $("bubble");
  // keep a half-typed answer or prompt; the next update redraws the bubble after it is sent
  if (host.contains(document.activeElement) && document.activeElement?.tagName === "TEXTAREA") return;
  if (!selected) { host.replaceChildren(); return; }

  let anchor: { x: number; y: number };
  let body;
  if (selected === "new") {
    anchor = { x: 310, y: 150 };
    body = newFlightForm(actions);
  } else {
    const p = state.planes.find((x) => x.session === selected);
    const spot = spots.get(selected!);
    if (!p || !spot) { host.replaceChildren(); return; }
    // circling planes are anchored where they are now; everything else where it is going
    const at = (spot.kind === "flying" && airport.scene.positionOf(p.session)) || spot;
    const lift = spot.kind === "queue" ? (spot.tag === "above" ? 150 : 70) : 50;
    anchor = { x: at.x, y: at.y - lift };
    body = p.need && !p.need.skipped ? decision(p, actions, editing, outputOpen) : flightCard(p, actions, outputOpen);
  }

  const toneName = selected === "new" ? "review" : tone(state.planes.find((x) => x.session === selected)!);
  const bubble = h("section", { class: `bubble tone-${toneName}` }, body);
  host.replaceChildren(bubble);
  // above the anchor, kept inside the picture
  const bw = 500;
  const left = Math.min(Math.max(anchor.x - bw / 2, 12), W - bw - 12);
  const height = bubble.offsetHeight;
  const below = anchor.y - height - 24 < 8;
  bubble.style.left = `${left}px`;
  bubble.style.top = `${below ? anchor.y + 200 : anchor.y - height - 24}px`;
  bubble.style.setProperty("--tail-x", `${Math.min(Math.max(anchor.x - left, 24), bw - 24)}px`);
  bubble.classList.toggle("is-below", below);
}

// ---------------------------------------------------------------- actions

async function post(url: string, body?: unknown) {
  const res = await fetch(url, { method: "POST", body: body === undefined ? undefined : JSON.stringify(body) }).catch(() => null);
  if (!res?.ok) console.warn(url, res && (await res.text()));
  return res;
}

function select(session: string | null) {
  selected = session;
  pinned = session !== null;
  outputOpen = false;
  editing = false;
  render();
}

function takeoff(session: string) {
  departing.add(session);
  airport.scene.takeoff(session, () => { departing.delete(session); render(); });
}

function answered() {
  selected = null;
  pinned = false;
  editing = false;
  render();
}

const actions: BubbleActions = {
  accept(p) {
    const card = p.need?.card;
    if (!card) return;
    if (card.proposal.action !== "dismiss") takeoff(p.session);
    answered();
    void post(`/api/answer/${p.session}`, { choice: "accept", key: p.need!.key });
  },
  startEdit() {
    editing = true;
    render();
    const t = $<HTMLTextAreaElement>("edit");
    t?.focus();
    t?.setSelectionRange(t.value.length, t.value.length);
  },
  sendEdit(p, action: Action) {
    const text = $<HTMLTextAreaElement>("edit")?.value.trim() ?? "";
    takeoff(p.session);
    answered();
    void post(`/api/answer/${p.session}`, { choice: "edit", action, text, key: p.need!.key });
  },
  cancelEdit() { editing = false; render(); },
  skip(p) { void post(`/api/answer/${p.session}`, { choice: "skip", key: p.need!.key }); },
  toggleOutput() { outputOpen = !outputOpen; render(); },
  focus(p) { void post(`/api/focus/${p.session}`); },
  sendPrompt(p) {
    const box = $<HTMLTextAreaElement>("prompt");
    const text = box?.value.trim();
    if (!text) return;
    box.blur();
    if (p.status !== "working") takeoff(p.session);
    answered();
    void post(`/api/prompt/${p.session}`, { text });
  },
  stop(p) { void post(`/api/stop/${p.session}`); },
  launch() {
    const repo = $<HTMLInputElement>("repo").value.trim();
    const box = $<HTMLTextAreaElement>("prompt");
    const prompt = box.value.trim();
    if (!repo || !prompt) return;
    try { localStorage.setItem("planesight:repo", repo); } catch { /* storage blocked */ }
    box.blur();
    const kind = $<HTMLSelectElement>("kind").value;
    answered();
    void post("/api/launch", { repo, prompt, kind });
  },
  close() { select(null); },
};

// ---------------------------------------------------------------- keyboard

document.addEventListener("keydown", (e) => {
  const target = e.target as HTMLElement;
  const inField = target.closest?.("input, textarea, select");
  const p: Plane | undefined = state.planes.find((x) => x.session === selected);
  if (e.key === "Escape") { editing = false; selected = null; pinned = true; target.blur?.(); render(); return; }
  if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
    e.preventDefault();
    if (selected === "new") actions.launch();
    else if (editing && p?.need?.card) actions.sendEdit(p, EDIT_ACTION[p.need.card.proposal.action] ?? p.need.card.proposal.action);
    else if (p && $("prompt")) actions.sendPrompt(p);
    return;
  }
  if (inField || target.closest?.("button")) return;
  const { queue } = groups(state, departing);
  if (e.key === "Enter" && p?.need && !p.need.skipped) {
    e.preventDefault();
    // a bubble that just opened is read before it is answered
    if (!e.repeat && Date.now() - shownAt > 700) actions.accept(p);
  } else if ((e.key === "e" || e.key === "E") && p?.need) { e.preventDefault(); actions.startEdit(); }
  else if ((e.key === "s" || e.key === "S") && p?.need) actions.skip(p);
  else if (e.key === "n" || e.key === "N") select("new");
  else if (["ArrowRight", "ArrowLeft", "ArrowUp", "ArrowDown", "Tab"].includes(e.key) && queue.length) {
    e.preventDefault();
    const i = queue.findIndex((x) => x.session === selected);
    const step = e.key === "ArrowLeft" || e.key === "ArrowDown" || (e.key === "Tab" && !e.shiftKey) ? 1 : -1;
    select(queue[(Math.max(i, 0) + step + queue.length) % queue.length].session);
  }
});

// waiting times tick without redrawing the bubble
setInterval(() => {
  const wait = document.querySelector(".bubble .wait");
  const p = state.planes.find((x) => x.session === selected);
  if (wait && p?.need?.since) wait.textContent = `${Math.max(0, Math.round((Date.now() - p.need.since) / 1000))} s`.replace(/^(\d+) s$/, (_, s) => (Number(s) < 60 ? `${s} s` : `${Math.floor(Number(s) / 60)} min`));
}, 1000);

// ---------------------------------------------------------------- boot

await document.fonts.ready;
fit();
const events = new EventSource("/events");
events.onmessage = (e) => {
  state = JSON.parse(e.data) as TowerState;
  render();
};

/* Plane Sight. The flight strips follow the promo's AirportAircraft tooltip:
   cream paper, a thick left edge, Courier type, the airline's colour, amber for the next plane. */
:root {
  --grass: #6c9c57;
  --ink: #23272d;
  --ink-soft: #526557;
  --paper: #f7f5e9;
  --paper-next: #fff0c9;
  --edge: #324e41;
  --edge-next: #9a692c;
  --cloud-code: #173e81;
  --openair: #105734;
  --approve: #d9534a;
  --decide: #3f7fd0;
  --review: #3f9a4f;
  --alert: #e0a020;
  --mono: "Courier New", ui-monospace, monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; }
body { background: var(--grass); color: var(--ink); font: 18px/1.45 var(--sans); }

.viewport { position: fixed; inset: 0; overflow: hidden; }

/* the stage is the picture's own pixel grid; main.ts scales it to the window */
.stage {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 1672px;
  height: 941px;
  transform: translate(-50%, -50%);
  transform-origin: center center;
}
#game { position: absolute; inset: 0; z-index: 0; }
#game canvas { display: block; }

.sign, .tower-label, .flight-label, .overflow-label, .logo { position: absolute; margin: 0; z-index: 1; pointer-events: none; }
.sign {
  left: 154px;
  top: 153px;
  padding: 6px 11px;
  border: 1px solid #829187;
  background: #dbe2d8;
  color: #3b543f;
  font: 700 13px/1 var(--mono);
  letter-spacing: 1px;
}
.tower-label, .flight-label, .overflow-label {
  font: 700 18px/1 var(--mono);
  color: #fff;
  text-shadow: 2px 2px 0 var(--ink);
}
.tower-label { left: 1335px; top: 268px; width: 200px; text-align: center; }
.flight-label { right: 34px; bottom: 30px; font-size: 22px; }
.overflow-label { left: 24px; top: 668px; }
.logo { left: 26px; bottom: 18px; width: 250px; }

/* ---------------------------------------------------------------- flight tags */

#tags { position: absolute; inset: 0; z-index: 2; pointer-events: none; }
.tag {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transition: opacity 200ms;
}
.tag > * { pointer-events: none; }
.tag::before { content: none; }
.tag .tag-line, .tag .tag-status { position: relative; }
.tag {
  --strip-bg: var(--paper);
  --strip-edge: var(--edge);
  --airline: var(--cloud-code);
}
.tag.openair { --airline: var(--openair); }
.tag.is-next { --strip-bg: var(--paper-next); --strip-edge: var(--edge-next); }
.tag-line, .tag-status { display: none; }
.tag { display: block; }
.tag::after { content: none; }
.tag > .tag-line, .tag > .tag-status { display: flex; }

.tag-line, .tag-status {
  position: absolute;
  left: -100px;
  width: 200px;
  background: var(--strip-bg);
  border: 2px solid var(--strip-edge);
  border-left-width: 6px;
  padding: 0 10px;
  white-space: nowrap;
  overflow: hidden;
}
.tag-line {
  align-items: baseline;
  gap: 8px;
  padding-top: 7px;
  padding-bottom: 3px;
  border-bottom: 0;
  color: var(--airline);
  font: 700 18px/1 var(--mono);
  letter-spacing: -0.4px;
}
.tag-line b { color: var(--ink-soft); font-size: 15px; }
.tag-line strong { overflow: hidden; text-overflow: ellipsis; }
.tag-line small { margin-left: auto; font-size: 11px; color: #66736b; letter-spacing: 0; }
.tag-status {
  padding-top: 3px;
  padding-bottom: 7px;
  border-top: 0;
  color: var(--ink-soft);
  font: 400 13px/1.1 var(--mono);
  box-shadow: 3px 3px 0 #334d4133;
}
.tag.is-next .tag-status { color: #86591c; }
.tag.tone-alert .tag-status { color: #a5630a; font-weight: 700; }
/* above: the strip sits over the plane at the hold line; below: under a plane on the taxiway */
.tag.is-above .tag-line { top: -142px; }
.tag.is-above .tag-status { top: -114px; }
.tag.is-below .tag-line { top: 62px; }
.tag.is-below .tag-status { top: 90px; }
.tag.is-selected .tag-line, .tag.is-selected .tag-status { border-color: #fff; }

/* ---------------------------------------------------------------- bubble */

#bubble { position: absolute; inset: 0; z-index: 3; pointer-events: none; }
.bubble {
  --tone: var(--edge);
  position: absolute;
  width: 500px;
  padding: 16px 18px 14px;
  background: var(--paper);
  border: 3px solid var(--edge);
  border-left: 8px solid var(--tone);
  box-shadow: 5px 5px 0 #334d4155;
  pointer-events: auto;
}
.bubble.tone-approve { --tone: var(--approve); }
.bubble.tone-decide { --tone: var(--decide); }
.bubble.tone-review { --tone: var(--review); }
.bubble.tone-alert { --tone: var(--alert); }
.bubble::after {
  content: "";
  position: absolute;
  left: var(--tail-x, 50%);
  bottom: -14px;
  width: 18px;
  height: 18px;
  background: var(--paper);
  border-right: 3px solid var(--edge);
  border-bottom: 3px solid var(--edge);
  transform: translateX(-50%) rotate(45deg);
}
.bubble.is-below::after { top: -14px; bottom: auto; transform: translateX(-50%) rotate(225deg); }

.bubble-head { display: flex; align-items: baseline; gap: 10px; margin-bottom: 8px; }
.bubble-head strong { font: 700 22px/1 var(--mono); flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bubble-head small { font: 400 12px/1 var(--mono); color: #66736b; white-space: nowrap; }
.bubble-head .kind { font: 700 14px/1 var(--mono); color: var(--tone); white-space: nowrap; }
.bubble-head .wait { margin-left: auto; color: var(--ink-soft); font-size: 14px; white-space: nowrap; }
.bubble p { margin: 0 0 10px; }
.bubble .summary { font-size: 17px; }
.bubble .collision { padding: 6px 10px; background: #fbe6b8; border-left: 4px solid var(--alert); font-size: 15px; }
.bubble .proposal { padding: 8px 10px; background: #ecebdc; font-size: 15px; }
.bubble .proposal b { display: block; font: 700 13px/1.2 var(--mono); color: var(--ink-soft); margin-bottom: 3px; }
.bubble textarea, .bubble .field {
  display: block;
  width: 100%;
  margin: 0 0 10px;
  padding: 8px 10px;
  font: inherit;
  font-size: 16px;
  border: 2px solid var(--edge);
  background: #fff;
  color: var(--ink);
}
.bubble textarea { min-height: 84px; resize: vertical; }
.bubble .output {
  margin: 10px 0 0;
  padding: 10px;
  max-height: 220px;
  overflow: auto;
  background: var(--ink);
  color: #e6e3da;
  font: 12px/1.4 ui-monospace, Menlo, monospace;
  white-space: pre-wrap;
}

.actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.actions .secondary { margin-left: auto; display: flex; gap: 6px; }
button {
  font: 700 16px/1 var(--mono);
  padding: 9px 12px 10px;
  border: 2px solid var(--edge);
  background: #fff;
  color: var(--ink);
  cursor: pointer;
  box-shadow: 3px 3px 0 #334d4155;
}
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #334d4155; }
button:disabled { opacity: .5; cursor: default; }
button.primary { background: var(--tone); border-color: var(--ink); color: #fff; }
button.small { padding: 6px 8px 7px; font-size: 13px; box-shadow: 2px 2px 0 #334d4155; }
button:focus-visible { outline: 3px solid var(--decide); outline-offset: 2px; }
button kbd { font: inherit; opacity: .7; margin-left: 6px; }

@media (prefers-reduced-motion: reduce) {
  .tag { transition: none; }
}

