 25	// Plane textures are drawn once at the next whole multiple and only ever shrink slightly.
 26	let RES = screenResolution();
 27	const TEX_RES = Math.ceil(RES);
 28	const PAD = 5;
 29	const TONE_COLOR: Record<Tone, string> = {
 30	  approve: "#d9534a",
 31	  decide: "#3f7fd0",
 32	  review: "#3f9a4f",
 33	  alert: "#e0a020",
 34	  parked: "#9aa1aa",
 35	  flying: "#ffffff",
 36	};
 37	
 38	export interface PlaneView {
 39	  session: string;
 40	  airline: Airline;
 41	  airframe: Airframe;
 42	  tone: Tone;
 43	  spot: Spot;
 44	}
 45	
 46	export interface AirportCallbacks {
 47	  onSelect: (session: string) => void;
 48	  onGround: (x: number, y: number) => void;
 49	  /** Every frame: where each plane is now, so the HTML strips can follow it. */
 50	  onFrame: (positions: Map<string, { x: number; y: number; visible: boolean }>) => void;
 51	}
 52	
 53	type PlaneObject = Phaser.GameObjects.Container & {
 54	  session: string;
 55	  sprite: string;
 56	  body: Phaser.GameObjects.Container;
 57	  shadow: Phaser.GameObjects.Image;
 58	  outline: Phaser.GameObjects.Image;
 59	  art: Phaser.GameObjects.Image;
 60	  spot?: Spot;
 61	  orbit?: { cx: number; cy: number; rx: number; ry: number; phase: number; speed: number } | null;
 62	  pulse?: Phaser.Tweens.Tween | null;
 63	  /** The running taxi or takeoff; a new one stops it, so two never fight over the position. */
 64	  move?: Phaser.Tweens.Tween | null;
 65	  departing?: boolean;
 66	};
 67	
 68	const entryById = (id?: string) => ENTRIES.find((e) => e.id === id);
 69	
 70	export class AirportScene extends Phaser.Scene {
 71	  private planes = new Map<string, PlaneObject>();
 72	  private views: PlaneView[] = [];
 73	  private selected: string | null = null;
 74	  private ready = false;
 75	  private bracket!: Phaser.GameObjects.Graphics;
 76	
 77	  constructor(private callbacks: AirportCallbacks, private roads: HTMLCanvasElement) {
 78	    super("airport");
 79	  }
 80	
 81	  preload() {
 82	    this.load.image("terrain", terrainUrl);
 83	    for (const [key, url] of Object.entries(SPRITES)) this.load.image(`src-${key}`, url);
 84	  }
 85	
 86	  create() {
 87	    this.cameras.main.setZoom(RES).centerOn(W / 2, H / 2);
 88	    // keep the terrain's pixel blocks hard when it is enlarged
 89	    this.textures.get("terrain").setFilter(Phaser.Textures.FilterMode.NEAREST);
 90	    // the terrain is 16:9 like the grid; cover it exactly, as the promo does
 91	    this.add.image(W / 2, H / 2, "terrain").setDisplaySize(W, H);
 92	    this.textures.addCanvas("roads", this.roads);
 93	    this.add.image(0, 0, "roads").setOrigin(0, 0).setDisplaySize(W, H);
 94	    for (const key of Object.keys(SPRITES)) this.makeTextures(key);
 95	    this.makePuff();
 96	    this.bracket = this.add.graphics().setDepth(40);
 97	    this.input.on("pointerdown", (pointer: Phaser.Input.Pointer, over: Phaser.GameObjects.GameObject[]) => {
 98	      if (!over.length) this.callbacks.onGround(pointer.worldX, pointer.worldY);
 99	    });
100	    this.ready = true;
101	    this.apply(this.views, this.selected);
102	  }
103	
104	  /** Per sprite: the plane at its size, a black shadow, and one outline per status colour. */
105	  private makeTextures(key: string) {
106	    const source = this.textures.get(`src-${key}`).getSourceImage() as HTMLImageElement;
107	    const size = PLANE_SIZE[key.endsWith("widebody") ? "widebody" : "narrowbody"] * TEX_RES;
108	    const tex = size + PAD * 2 * TEX_RES;
109	    const canvas = () => {
110	      const c = document.createElement("canvas");
111	      c.width = c.height = tex;
112	      return c;
113	    };
114	    const plane = canvas();
115	    const ctx = plane.getContext("2d")!;
116	    ctx.imageSmoothingQuality = "high";
117	    ctx.drawImage(source, PAD * TEX_RES, PAD * TEX_RES, size, size);
118	    this.textures.addCanvas(`plane-${key}`, plane);
119	
120	    const silhouette = (color: string, spread: number) => {
121	      const c = canvas();
122	      const s = c.getContext("2d")!;
123	      if (spread === 0) s.drawImage(plane, 0, 0);
124	      else for (let dx = -spread; dx <= spread; dx += spread) for (let dy = -spread; dy <= spread; dy += spread) s.drawImage(plane, dx, dy);
125	      s.globalCompositeOperation = "source-in";
126	      s.fillStyle = color;
127	      s.fillRect(0, 0, tex, tex);
128	      return c;
129	    };
130	    this.textures.addCanvas(`shadow-${key}`, silhouette("#000", 0));
131	    for (const [tone, color] of Object.entries(TONE_COLOR)) this.textures.addCanvas(`outline-${key}-${tone}`, silhouette(color, 3 * TEX_RES));
132	  }
133	
134	  private makePuff() {
135	    const c = document.createElement("canvas");
136	    c.width = c.height = 6;
137	    const ctx = c.getContext("2d")!;
138	    ctx.fillStyle = "#ffffff";
139	    ctx.fillRect(0, 0, 6, 6);
140	    this.textures.addCanvas("puff", c);
141	  }
142	
143	  update(_time: number, delta: number) {
144	    const positions = new Map<string, { x: number; y: number; visible: boolean }>();
145	    for (const plane of this.planes.values()) {
146	      const o = plane.orbit;
147	      // planes in flight circle slowly, unless you are looking at one
148	      if (o && !plane.departing && plane.session !== this.selected) {
149	        o.phase += (delta / 1000) * o.speed;
150	        plane.setPosition(o.cx + o.rx * Math.cos(o.phase), o.cy + o.ry * Math.sin(o.phase));
151	        plane.body.rotation = Math.atan2(o.ry * Math.cos(o.phase), -o.rx * Math.sin(o.phase)) + Math.PI / 2;
152	      }
153	      positions.set(plane.session, { x: plane.x, y: plane.y, visible: !plane.departing && plane.alpha > 0.5 });
154	    }
155	    this.callbacks.onFrame(positions);
156	    this.drawBracket();
157	  }
158	
159	  private makePlane(view: PlaneView): PlaneObject {
160	    const key = `${view.airline}-${view.airframe}`;
161	    const scale = 1 / TEX_RES;
162	    const shadow = this.add.image(5, 5, `shadow-${key}`).setAlpha(0.22).setScale(scale);
163	    const outline = this.add.image(0, 0, `outline-${key}-${view.tone}`).setVisible(false).setScale(scale);
164	    const art = this.add.image(0, 0, `plane-${key}`).setScale(scale);
165	    const body = this.add.container(0, 0, [shadow, outline, art]);
166	    const plane = this.add.container(0, 0, [body]) as PlaneObject;
167	    Object.assign(plane, { session: view.session, sprite: key, body, shadow, outline, art });
168	    const hit = PLANE_SIZE[view.airframe] * 0.7;
169	    plane.setSize(hit, hit).setInteractive({ useHandCursor: true });
170	    plane.on("pointerdown", () => this.callbacks.onSelect(view.session));
171	    return plane;
172	  }
173	
174	  apply(views: PlaneView[], selected: string | null) {
175	    this.views = views;
176	    this.selected = selected;
177	    if (!this.ready) return;
178	    const seen = new Set<string>();
179	
180	    for (const view of views) {
181	      seen.add(view.session);
182	      let plane = this.planes.get(view.session);
183	      if (plane?.departing) continue;
184	      const spot = view.spot;
185	      const isNew = !plane;
186	      if (!plane) {
187	        plane = this.makePlane(view);
188	        this.planes.set(view.session, plane);
189	        // a new plane in the queue taxis in from the west end of its taxiway; others fade in in place
190	        const entry = entryById(spot.entry);
191	        if (spot.kind === "queue" && entry) plane.setPosition(-70, entry.taxiY);
192	        else plane.setPosition(spot.x, spot.y).setAlpha(0);
193	        plane.body.setAngle(spot.kind === "queue" ? 90 : spot.heading).setScale(spot.scale);
194	      }
195	
196	      const key = `${view.airline}-${view.airframe}`;
197	      if (plane.sprite !== key) {
198	        plane.sprite = key;
199	        plane.art.setTexture(`plane-${key}`);
200	        plane.shadow.setTexture(`shadow-${key}`);
201	      }
202	      plane.setDepth(spot.kind === "flying" ? 30 : spot.kind === "queue" ? 20 - (spot.rank ?? 0) * 0.01 : 10);
203	      plane.outline.setTexture(`outline-${key}-${view.tone}`).setVisible(spot.kind === "queue");
204	      const lift = spot.kind === "flying" ? 26 : 5;
205	      plane.shadow.setPosition(lift, lift);
206	      this.setPulse(plane, spot.kind === "queue" && spot.rank === 0);
207	
208	      if (spot.kind === "flying") {
209	        if (!plane.orbit) {
210	          this.stopMoving(plane);
211	          plane.orbit = { cx: spot.x, cy: spot.y, rx: 44, ry: 12, phase: Math.random() * Math.PI * 2, speed: 0.3 + Math.random() * 0.15 };
212	          this.tweens.add({ targets: plane, alpha: 0.92, duration: 600 });
213	          this.tweens.add({ targets: plane.body, scale: spot.scale, duration: 600 });
214	        } else {
215	          plane.orbit.cx = spot.x;
216	          plane.orbit.cy = spot.y;
217	        }
218	      } else {
219	        plane.orbit = null;
220	        if (isNew || plane.spot?.x !== spot.x || plane.spot?.y !== spot.y) this.moveTo(plane, spot);
221	      }
222	      plane.spot = spot;
223	    }
224	
225	    for (const [session, plane] of this.planes) {
226	      if (seen.has(session) || plane.departing) continue;
227	      this.planes.delete(session);
228	      this.stopMoving(plane);
229	      this.tweens.add({ targets: plane, alpha: 0, duration: 400, onComplete: () => plane.destroy() });
230	    }
231	  }
232	
233	  private stopMoving(plane: PlaneObject) {
234	    plane.move?.stop();
235	    plane.move = null;
236	    this.tweens.killTweensOf([plane, plane.body]);
237	  }
238	
239	  /** The route to a spot: along the plane's taxiway and down its entry when it can, else straight there. */
240	  private route(plane: PlaneObject, spot: Spot) {
241	    const entry = entryById(spot.entry);
242	    const onItsTaxiway = entry && Math.abs(plane.y - entry.taxiY) < 6 && plane.x <= (spot.x === entry.hold.x ? entry.startX : spot.x) + 4;
243	    if (spot.kind === "queue" && entry && onItsTaxiway) {
244	      const path = new Phaser.Curves.Path(plane.x, plane.y);
245	      if (spot.x === entry.hold.x && spot.y === entry.hold.y) {
246	        path.lineTo(entry.startX, entry.taxiY);
247	        append(path, pathFromSvg(entry.d, entry.hold));
248	      } else {
249	        path.lineTo(spot.x, spot.y);
250	      }
251	      return { path, steer: true };
252	    }
253	    return { path: new Phaser.Curves.Path(plane.x, plane.y).lineTo(spot.x, spot.y), steer: false };
254	  }
255	
256	  private moveTo(plane: PlaneObject, spot: Spot) {
257	    this.stopMoving(plane);
258	    const { path, steer } = this.route(plane, spot);
259	    const length = path.getLength();
260	    if (length < 1) {
261	      this.tweens.add({ targets: plane, alpha: 1, duration: 400 });
262	      this.tweens.add({ targets: plane.body, angle: spot.heading, scale: spot.scale, duration: 400 });
263	      return;
264	    }
265	    const startScale = plane.body.scale;
266	    const startAngle = plane.body.angle;
267	    const turn = Phaser.Math.Angle.ShortestBetween(startAngle, spot.heading);
268	    plane.move = this.tweens.addCounter({
269	      from: 0,
270	      to: 1,
271	      duration: Phaser.Math.Clamp(length * 3.2, 500, 3200),
272	      ease: "Sine.easeInOut",
273	      onUpdate: (tween) => {
274	        const t = tween.getValue() ?? 0;
275	        const point = path.getPoint(t);
276	        plane.setPosition(point.x, point.y);
277	        plane.setAlpha(Math.max(plane.alpha, Math.min(1, t * 3)));
278	        plane.body.setScale(startScale + (spot.scale - startScale) * t);
279	        if (steer) {
280	          const tangent = path.getTangent(Math.min(t, 0.995));
281	          plane.body.rotation = Math.atan2(tangent.y, tangent.x) + Math.PI / 2;
282	        } else {
283	          plane.body.setAngle(startAngle + turn * Math.min(1, t * 1.5));
284	        }
285	      },
286	      onComplete: () => {
287	        plane.move = null;
288	        plane.setAlpha(1);
289	        this.tweens.add({ targets: plane.body, angle: plane.body.angle + Phaser.Math.Angle.ShortestBetween(plane.body.angle, spot.heading), duration: 250 });
290	      },
291	    });
292	  }
293	
294	  private setPulse(plane: PlaneObject, on: boolean) {
295	    if (on && !plane.pulse) {
296	      plane.pulse = this.tweens.add({ targets: plane.outline, alpha: 0.3, duration: 900, yoyo: true, repeat: -1, ease: "Sine.easeInOut" });
297	    } else if (!on && plane.pulse) {
298	      plane.pulse.stop();
299	      plane.pulse = null;
300	      plane.outline.setAlpha(1);
301	    }
302	  }
303	
304	  private drawBracket() {
305	    this.bracket.clear();
306	    const plane = this.selected ? this.planes.get(this.selected) : null;
307	    if (!plane || plane.departing) return;
308	    const size = PLANE_SIZE[plane.sprite.endsWith("widebody") ? "widebody" : "narrowbody"];
309	    const r = (size / 2) * plane.body.scale * 0.85;
310	    this.bracket.lineStyle(3, 0xffffff, 0.95);
311	    for (const [dx, dy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
312	      const x = plane.x + dx * r;
313	      const y = plane.y + dy * r;
314	      this.bracket.lineBetween(x, y, x - dx * 12, y);
315	      this.bracket.lineBetween(x, y, x, y - dy * 12);
316	    }
317	  }
318	
319	  positionOf(session: string) {
320	    const plane = this.planes.get(session);
321	    return plane ? { x: plane.x, y: plane.y } : null;
322	  }
323	
324	  /** The way to the runway from where the plane is, then the roll east and the climb out. */
325	  private departure(plane: PlaneObject) {
326	    const entry = entryById(plane.spot?.entry);
327	    const path = new Phaser.Curves.Path(plane.x, plane.y);
328	    if (entry && plane.spot?.kind === "queue") {
329	      const atHold = Math.abs(plane.x - entry.hold.x) < 4 && Math.abs(plane.y - entry.hold.y) < 4;
330	      if (atHold) append(path, restOfEntry(entry));
331	      else {
332	        path.lineTo(entry.startX, entry.taxiY);
333	        append(path, pathFromSvg(entry.d));
334	      }
335	    } else {
336	      // from a stand or anywhere else: straight onto the runway
337	      path.lineTo(Math.max(plane.x, 120), RUNWAY_Y);
338	    }
339	    const rollFrom = path.getLength();
340	    path.lineTo(1235, RUNWAY_Y);
341	    path.lineTo(1380, RUNWAY_Y - 60);
342	    return { path, rollStart: rollFrom / path.getLength() };
343	  }
344	
345	  /** The big moment: down the entry, onto the runway, roll with exhaust, lift off the east edge. */
346	  takeoff(session: string, done: () => void) {
347	    const plane = this.planes.get(session);
348	    if (!plane || plane.departing) return done();
349	    plane.departing = true;
350	    plane.orbit = null;
351	    this.setPulse(plane, false);
352	    this.stopMoving(plane);
353	    plane.outline.setVisible(false);
354	    plane.disableInteractive();
355	
356	    const { path, rollStart } = this.departure(plane);
357	    const exhaust = this.add.particles(0, 0, "puff", {
358	      speed: { min: 6, max: 22 },
359	      lifespan: 650,
360	      scale: { start: 1.2, end: 0 },
361	      alpha: { start: 0.55, end: 0 },
362	      frequency: 22,
363	      emitting: false,
364	    }).setDepth(plane.depth - 1);
365	    exhaust.startFollow(plane);
366	
367	    const startScale = plane.body.scale;
368	    plane.move = this.tweens.addCounter({
369	      from: 0,
370	      to: 1,
371	      duration: 2200 + path.getLength() * 1.2,
372	      ease: "Quad.easeIn",
373	      onUpdate: (tween) => {
374	        const t = tween.getValue() ?? 0;
375	        const point = path.getPoint(t);
376	        const tangent = path.getTangent(Math.min(t, 0.995));
377	        plane.setPosition(point.x, point.y);
378	        plane.body.rotation = Math.atan2(tangent.y, tangent.x) + Math.PI / 2;
379	        if (t > rollStart && !exhaust.emitting) exhaust.start();
380	        const lift = Phaser.Math.Clamp((t - 0.88) / 0.12, 0, 1);
381	        plane.body.setScale(startScale + 0.4 * lift);
382	        plane.shadow.setPosition(5 + 34 * lift, 5 + 42 * lift);
383	      },
384	      onComplete: () => {
385	        exhaust.stop();
386	        this.time.delayedCall(900, () => exhaust.destroy());
387	        this.planes.delete(session);
388	        plane.destroy();
389	        done();
390	      },
391	    });
392	  }
393	}
394	
395	/** Appends the curves of one path to another; Phaser's add() takes single curves only. */
396	function append(path: Phaser.Curves.Path, more: Phaser.Curves.Path) {
397	  for (const curve of more.curves) path.add(curve);
398	}
399	
400	/** From the hold mark to the end of the entry, where it meets the runway. */
401	function restOfEntry(entry: Entry) {
402	  const m = entry.d.match(/L (\d+) (\d+) Q (\d+) (\d+) (\d+) (\d+)$/);
403	  const path = new Phaser.Curves.Path(entry.hold.x, entry.hold.y);
404	  if (!m) return path.lineTo(entry.hold.x + 60, RUNWAY_Y);
405	  const [lx, ly, cx, cy, ex, ey] = m.slice(1).map(Number);
406	  path.lineTo(lx, ly);
407	  path.quadraticBezierTo(ex, ey, cx, cy);
408	  return path;
409	}
410	
411	export function createAirport(parent: HTMLElement, callbacks: AirportCallbacks, roads: HTMLCanvasElement) {
412	  const scene = new AirportScene(callbacks, roads);
413	  // The canvas has the screen's pixels and is shown at grid size (zoom 1 / RES), so it maps 1:1
414	  // onto the display; the camera zoom keeps the world in grid coordinates.
415	  const game = new Phaser.Game({
416	    type: Phaser.AUTO,
417	    parent,
418	    width: Math.round(W * RES),
419	    height: Math.round(H * RES),
420	    transparent: true,
421	    scale: { mode: Phaser.Scale.NONE, zoom: 1 / RES },
422	    scene,
423	  });
424	  return {
425	    scene,
426	    /** After a window resize: render at the new screen resolution, then let Phaser re-read the canvas size. */
427	    refresh: () => {
428	      const next = screenResolution();
429	      if (Math.abs(next - RES) > 0.01 && game.isBooted) {
430	        RES = next;
431	        game.scale.resize(Math.round(W * RES), Math.round(H * RES));
432	        game.scale.setZoom(1 / RES);
433	        scene.cameras.main?.setZoom(RES).centerOn(W / 2, H / 2);
434	      }
435	      game.scale.refresh();
436	    },
437	  };
438	}

/* Plane Sight. The flight strips follow the promo's AirportAircraft tooltip:
   cream paper, a thick left edge, Courier type, the airline's colour, amber for the next plane. */
:root {
  --grass: #6c9c57;
  --ink: #23272d;
  --ink-soft: #526557;
  --paper: #f7f5e9;
  --paper-next: #fff0c9;
  --edge: #324e41;
  --edge-next: #9a692c;
  --cloud-code: #a3410e;
  --openair: #105734;
  --approve: #d9534a;
  --decide: #3f7fd0;
  --review: #3f9a4f;
  --alert: #e0a020;
  --mono: "Courier New", ui-monospace, monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; overflow: hidden; }
body { background: var(--grass); color: var(--ink); font: 18px/1.45 var(--sans); }

.viewport { position: fixed; inset: 0; overflow: hidden; }

/* ---------------------------------------------------------------- flight tags */

#tags { position: absolute; inset: 0; z-index: 2; pointer-events: none; }
.tag {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transition: opacity 200ms;
}
.tag > * { pointer-events: none; }
.tag {
  --strip-bg: var(--paper);
  --strip-edge: var(--edge);
  --airline: var(--cloud-code);
}
.tag.openair { --airline: var(--openair); }
.tag.is-next { --strip-bg: var(--paper-next); --strip-edge: var(--edge-next); }

.tag-line, .tag-status {
  position: absolute;
  left: -90px;
  width: 180px;
  background: var(--strip-bg);
  border: 2px solid var(--strip-edge);
  border-left-width: 6px;
  padding: 0 10px;
  white-space: nowrap;
  overflow: hidden;
}
.tag-line {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding-top: 7px;
  padding-bottom: 3px;
  border-bottom: 0;
  color: var(--airline);
  font: 700 15px/1 var(--mono);
  letter-spacing: -0.4px;
}
.tag-line b { color: var(--ink-soft); font-size: 13px; }
.tag-line strong { overflow: hidden; text-overflow: ellipsis; }
.tag-line small { margin-left: auto; font-size: 11px; color: #66736b; letter-spacing: 0; }
.tag-status {
  display: block;
  padding-top: 3px;
  padding-bottom: 7px;
  border-top: 0;
  color: var(--ink-soft);
  font: 400 11px/1.1 var(--mono);
  box-shadow: 3px 3px 0 #334d4133;
}
.tag.is-next .tag-status { color: #86591c; }
.tag.tone-alert .tag-status { color: #a5630a; font-weight: 700; }
/* above: the strip sits over the plane at the hold line; below: under a plane on the taxiway */
/* left: beside a plane at a hold mark; above / below: over or under a plane on a taxiway */
.tag.is-left .tag-line { left: -232px; top: -30px; }
.tag.is-left .tag-status { left: -232px; top: -6px; }
.tag.is-above .tag-line { top: -88px; }
.tag.is-above .tag-status { top: -64px; }
.tag.is-below .tag-line { top: 38px; }
.tag.is-below .tag-status { top: 62px; }
.tag.is-selected .tag-line, .tag.is-selected .tag-status { border-color: #fff; }

/* ---------------------------------------------------------------- bubble */

#bubble { position: absolute; inset: 0; z-index: 3; pointer-events: none; }
