async () => {
  const c = document.querySelector("#game canvas");
  const at = { clientX: 345 * 0.72, clientY: 730 * 0.72, bubbles: true, pointerId: 1, isPrimary: true, button: 0, buttons: 1 };
  for (const t of ["pointerdown", "mousedown"]) c.dispatchEvent(new (t.startsWith("pointer") ? PointerEvent : MouseEvent)(t, at));
  for (const t of ["pointerup", "mouseup"]) c.dispatchEvent(new (t.startsWith("pointer") ? PointerEvent : MouseEvent)(t, { ...at, buttons: 0 }));
  await new Promise(r => setTimeout(r, 400));
  const { selected } = window.planesight.debug();
  const p = window.planesight.state().planes.find(x => x.session === selected);
  return { selected: p?.name, bubble: document.querySelector(".bubble-head strong")?.textContent };
}

