40:/** Parses the M, L, H, V and Q commands that the layout uses into a Phaser path. */
41:export function pathFromSvg(d: string, upTo?: { x: number; y: number }) {
42:  const tokens = d.match(/[MLHVQ]|-?\d+(\.\d+)?/g) ?? [];
43:  let path: Phaser.Curves.Path | null = null;
44:  let x = 0;
45:  let y = 0;
46:  for (let i = 0; i < tokens.length; ) {
47:    const cmd = tokens[i++];
48:    const n = () => Number(tokens[i++]);
49:    if (cmd === "M") { x = n(); y = n(); path = new Phaser.Curves.Path(x, y); continue; }
50:    if (!path) throw new Error(`path data must start with M: ${d}`);
51:    if (cmd === "L") { x = n(); y = n(); }
52:    else if (cmd === "H") x = n();
53:    else if (cmd === "V") y = n();
54:    else if (cmd === "Q") {
55:      const cx = n(), cy = n();
56:      x = n(); y = n();
57:      path.quadraticBezierTo(x, y, cx, cy);
58:      continue;
59:    }
60:    // stop at a point on this straight segment (the hold mark), if asked
61:    if (upTo && isBetween(path.getEndPoint(), { x, y }, upTo)) {
62:      path.lineTo(upTo.x, upTo.y);
63:      return path;
64:    }
65:    path.lineTo(x, y);
66:  }
67:  return path!;
68:}
