70:function isBetween(a: Phaser.Math.Vector2, b: { x: number; y: number }, p: { x: number; y: number }) {
71:  const cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
72:  const within = Math.min(a.x, b.x) - 1 <= p.x && p.x <= Math.max(a.x, b.x) + 1 && Math.min(a.y, b.y) - 1 <= p.y && p.y <= Math.max(a.y, b.y) + 1;
73:  return within && Math.abs(cross) < 600;
74:}
